CREATE OR REPLACE FUNCTION private.autorizar_analise_evidencia_logistica()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  evidencia record;
BEGIN
  IF NOT EXISTS (
    SELECT 1
    FROM public.evidencia_logistica_versoes elv
    WHERE elv.documento_versao_id = NEW.documento_versao_id
  ) THEN
    RETURN NEW;
  END IF;

  IF auth.uid() IS NULL OR public.get_user_role() <> 'gestor' THEN
    RAISE EXCEPTION 'Somente gestor autorizado pode analisar evidencia logistica antecipada'
      USING ERRCODE = '42501';
  END IF;

  FOR evidencia IN
    SELECT DISTINCT ela.fundo_id
    FROM public.evidencia_logistica_versoes elv
    JOIN public.evidencias_logisticas_antecipadas ela
      ON ela.id = elv.evidencia_logistica_id
    WHERE elv.documento_versao_id = NEW.documento_versao_id
  LOOP
    IF NOT private.usuario_tem_acesso_fundo(evidencia.fundo_id) THEN
      RAISE EXCEPTION 'Gestor sem acesso ao fundo da evidencia logistica'
        USING ERRCODE = '42501';
    END IF;
  END LOOP;

  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.admin_atualizar_fundo(p_fundo_id uuid, p_updated_at_esperado timestamp with time zone, p_nome text, p_cnpj text, p_administradora_nome text, p_administradora_cnpj text, p_gestora_nome text, p_gestora_cnpj text, p_custodiante_nome text DEFAULT NULL::text, p_custodiante_cnpj text DEFAULT NULL::text, p_administradora_endereco text DEFAULT NULL::text, p_administradora_ato_declaratorio text DEFAULT NULL::text, p_contato_nome text DEFAULT NULL::text, p_contato_email text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_atual public.fundos%ROWTYPE;
  v_antes jsonb;
  v_depois jsonb;
  v_cnpj text := regexp_replace(COALESCE(p_cnpj, ''), '[^0-9]', '', 'g');
  v_administradora_cnpj text := regexp_replace(COALESCE(p_administradora_cnpj, ''), '[^0-9]', '', 'g');
  v_gestora_cnpj text := regexp_replace(COALESCE(p_gestora_cnpj, ''), '[^0-9]', '', 'g');
  v_custodiante_cnpj text := NULLIF(regexp_replace(COALESCE(p_custodiante_cnpj, ''), '[^0-9]', '', 'g'), '');
BEGIN
  IF NOT (SELECT private.usuario_e_super_admin()) THEN
    RAISE EXCEPTION 'Acesso administrativo negado' USING ERRCODE = '42501';
  END IF;
  IF p_updated_at_esperado IS NULL THEN
    RAISE EXCEPTION 'Versao esperada do cadastro e obrigatoria' USING ERRCODE = '22023';
  END IF;
  IF NULLIF(trim(COALESCE(p_nome, '')), '') IS NULL
     OR NULLIF(trim(COALESCE(p_administradora_nome, '')), '') IS NULL
     OR NULLIF(trim(COALESCE(p_gestora_nome, '')), '') IS NULL THEN
    RAISE EXCEPTION 'Nome do fundo, administradora e gestora sao obrigatorios' USING ERRCODE = '22023';
  END IF;
  IF NULLIF(trim(COALESCE(p_contato_email, '')), '') IS NOT NULL
     AND trim(p_contato_email) !~* '^[^@[:space:]]+@[^@[:space:]]+\.[^@[:space:]]+$' THEN
    RAISE EXCEPTION 'E-mail de contato invalido' USING ERRCODE = '22023';
  END IF;
  IF NOT (SELECT private.cnpj_valido(v_cnpj))
     OR NOT (SELECT private.cnpj_valido(v_administradora_cnpj))
     OR NOT (SELECT private.cnpj_valido(v_gestora_cnpj))
     OR (v_custodiante_cnpj IS NOT NULL AND NOT (SELECT private.cnpj_valido(v_custodiante_cnpj))) THEN
    RAISE EXCEPTION 'CNPJ invalido' USING ERRCODE = '22023';
  END IF;

  SELECT * INTO v_atual FROM public.fundos WHERE id = p_fundo_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Fundo nao encontrado' USING ERRCODE = 'P0002'; END IF;
  IF v_atual.updated_at IS DISTINCT FROM p_updated_at_esperado THEN
    RAISE EXCEPTION 'O fundo foi alterado por outro usuario. Recarregue a pagina.' USING ERRCODE = '40001';
  END IF;
  IF v_atual.nome IS NOT DISTINCT FROM trim(p_nome)
     AND v_atual.cnpj IS NOT DISTINCT FROM v_cnpj
     AND v_atual.administradora_nome IS NOT DISTINCT FROM trim(p_administradora_nome)
     AND v_atual.administradora_cnpj IS NOT DISTINCT FROM v_administradora_cnpj
     AND v_atual.gestora_nome IS NOT DISTINCT FROM trim(p_gestora_nome)
     AND v_atual.gestora_cnpj IS NOT DISTINCT FROM v_gestora_cnpj
     AND v_atual.custodiante_nome IS NOT DISTINCT FROM NULLIF(trim(COALESCE(p_custodiante_nome, '')), '')
     AND v_atual.custodiante_cnpj IS NOT DISTINCT FROM v_custodiante_cnpj
     AND v_atual.administradora_endereco IS NOT DISTINCT FROM NULLIF(trim(COALESCE(p_administradora_endereco, '')), '')
     AND v_atual.administradora_ato_declaratorio IS NOT DISTINCT FROM NULLIF(trim(COALESCE(p_administradora_ato_declaratorio, '')), '')
     AND v_atual.contato_nome IS NOT DISTINCT FROM NULLIF(trim(COALESCE(p_contato_nome, '')), '')
     AND v_atual.contato_email IS NOT DISTINCT FROM NULLIF(lower(trim(COALESCE(p_contato_email, ''))), '') THEN
    RETURN public.admin_obter_fundo(p_fundo_id);
  END IF;

  SELECT public.admin_obter_fundo(p_fundo_id) INTO v_antes;
  UPDATE public.fundos
     SET nome = trim(p_nome),
         cnpj = v_cnpj,
         administradora_nome = trim(p_administradora_nome),
         administradora_cnpj = v_administradora_cnpj,
         gestora_nome = trim(p_gestora_nome),
         gestora_cnpj = v_gestora_cnpj,
         custodiante_nome = NULLIF(trim(COALESCE(p_custodiante_nome, '')), ''),
         custodiante_cnpj = v_custodiante_cnpj,
         administradora_endereco = NULLIF(trim(COALESCE(p_administradora_endereco, '')), ''),
         administradora_ato_declaratorio = NULLIF(trim(COALESCE(p_administradora_ato_declaratorio, '')), ''),
         contato_nome = NULLIF(trim(COALESCE(p_contato_nome, '')), ''),
         contato_email = NULLIF(lower(trim(COALESCE(p_contato_email, ''))), '')
   WHERE id = p_fundo_id;

  SELECT public.admin_obter_fundo(p_fundo_id) INTO v_depois;
  IF (v_antes - 'updated_at') IS DISTINCT FROM (v_depois - 'updated_at') THEN
    PERFORM private.registrar_auditoria_fundo('FUNDO_ATUALIZADO', p_fundo_id, v_antes, v_depois);
  END IF;
  RETURN v_depois;
END;
$function$

CREATE OR REPLACE FUNCTION public.admin_conceder_super_admin(p_usuario_id uuid, p_correlation_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_perfil public.profiles%ROWTYPE;
  v_ja_ativo boolean;
BEGIN
  IF NOT (SELECT private.usuario_e_super_admin()) THEN RAISE EXCEPTION 'Acesso administrativo negado' USING ERRCODE = '42501'; END IF;
  SELECT * INTO v_perfil FROM public.profiles p WHERE p.id = p_usuario_id FOR UPDATE;
  IF NOT FOUND OR v_perfil.role::text <> 'gestor' THEN RAISE EXCEPTION 'Somente um Gestor pode receber capacidade Super Admin complementar' USING ERRCODE = '22023'; END IF;
  SELECT EXISTS (SELECT 1 FROM public.usuario_papeis up WHERE up.usuario_id = p_usuario_id AND up.papel::text = 'super_admin' AND up.ativo IS TRUE) INTO v_ja_ativo;
  IF v_ja_ativo THEN RETURN public.admin_obter_usuario(p_usuario_id); END IF;
  INSERT INTO public.usuario_papeis (usuario_id, papel, ativo, origem, atribuido_por, atribuido_em, revogado_em)
  VALUES (p_usuario_id, 'super_admin'::public.user_role, true, 'administracao', (SELECT auth.uid()), now(), NULL)
  ON CONFLICT (usuario_id, papel) DO UPDATE SET ativo = true, origem = 'administracao', atribuido_por = EXCLUDED.atribuido_por, atribuido_em = now(), revogado_em = NULL;
  PERFORM private.registrar_auditoria_usuario('SUPER_ADMIN_CONCEDIDO', p_usuario_id, NULL, NULL, jsonb_build_object('papel_primario', v_perfil.role, 'super_admin', true), p_correlation_id);
  RETURN public.admin_obter_usuario(p_usuario_id);
END;
$function$

CREATE OR REPLACE FUNCTION public.admin_criar_fundo(p_nome text, p_cnpj text, p_administradora_nome text, p_administradora_cnpj text, p_gestora_nome text, p_gestora_cnpj text, p_custodiante_nome text DEFAULT NULL::text, p_custodiante_cnpj text DEFAULT NULL::text, p_administradora_endereco text DEFAULT NULL::text, p_administradora_ato_declaratorio text DEFAULT NULL::text, p_contato_nome text DEFAULT NULL::text, p_contato_email text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_id uuid;
  v_cnpj text := regexp_replace(COALESCE(p_cnpj, ''), '[^0-9]', '', 'g');
  v_administradora_cnpj text := regexp_replace(COALESCE(p_administradora_cnpj, ''), '[^0-9]', '', 'g');
  v_gestora_cnpj text := regexp_replace(COALESCE(p_gestora_cnpj, ''), '[^0-9]', '', 'g');
  v_custodiante_cnpj text := NULLIF(regexp_replace(COALESCE(p_custodiante_cnpj, ''), '[^0-9]', '', 'g'), '');
  v_depois jsonb;
BEGIN
  IF NOT (SELECT private.usuario_e_super_admin()) THEN
    RAISE EXCEPTION 'Acesso administrativo negado' USING ERRCODE = '42501';
  END IF;
  IF NULLIF(trim(COALESCE(p_nome, '')), '') IS NULL
     OR NULLIF(trim(COALESCE(p_administradora_nome, '')), '') IS NULL
     OR NULLIF(trim(COALESCE(p_gestora_nome, '')), '') IS NULL THEN
    RAISE EXCEPTION 'Nome do fundo, administradora e gestora sao obrigatorios' USING ERRCODE = '22023';
  END IF;
  IF NULLIF(trim(COALESCE(p_contato_email, '')), '') IS NOT NULL
     AND trim(p_contato_email) !~* '^[^@[:space:]]+@[^@[:space:]]+\.[^@[:space:]]+$' THEN
    RAISE EXCEPTION 'E-mail de contato invalido' USING ERRCODE = '22023';
  END IF;
  IF NOT (SELECT private.cnpj_valido(v_cnpj))
     OR NOT (SELECT private.cnpj_valido(v_administradora_cnpj))
     OR NOT (SELECT private.cnpj_valido(v_gestora_cnpj))
     OR (v_custodiante_cnpj IS NOT NULL AND NOT (SELECT private.cnpj_valido(v_custodiante_cnpj))) THEN
    RAISE EXCEPTION 'CNPJ invalido' USING ERRCODE = '22023';
  END IF;

  INSERT INTO public.fundos (
    nome, cnpj, administradora_nome, administradora_cnpj,
    gestora_nome, gestora_cnpj, custodiante_nome, custodiante_cnpj,
    administradora_endereco, administradora_ato_declaratorio,
    contato_nome, contato_email, ativo, created_by, created_at, updated_at
  )
  VALUES (
    trim(p_nome), v_cnpj, trim(p_administradora_nome), v_administradora_cnpj,
    trim(p_gestora_nome), v_gestora_cnpj, NULLIF(trim(COALESCE(p_custodiante_nome, '')), ''), v_custodiante_cnpj,
    NULLIF(trim(COALESCE(p_administradora_endereco, '')), ''), NULLIF(trim(COALESCE(p_administradora_ato_declaratorio, '')), ''),
    NULLIF(trim(COALESCE(p_contato_nome, '')), ''), NULLIF(lower(trim(COALESCE(p_contato_email, ''))), ''),
    false, (SELECT auth.uid()), now(), now()
  )
  RETURNING id INTO v_id;

  SELECT public.admin_obter_fundo(v_id) INTO v_depois;
  PERFORM private.registrar_auditoria_fundo('FUNDO_CRIADO', v_id, NULL, v_depois);
  RETURN v_depois;
END;
$function$

CREATE OR REPLACE FUNCTION public.admin_finalizar_convite_usuario(p_usuario_id uuid, p_tipo text, p_nome text, p_fundo_ids uuid[], p_correlation_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_perfil public.profiles%ROWTYPE;
BEGIN
  IF NOT (SELECT private.usuario_e_super_admin()) THEN RAISE EXCEPTION 'Acesso administrativo negado' USING ERRCODE = '42501'; END IF;
  IF p_tipo NOT IN ('gestor', 'super_admin') OR NULLIF(trim(COALESCE(p_nome, '')), '') IS NULL THEN
    RAISE EXCEPTION 'Dados do convite invalidos' USING ERRCODE = '22023';
  END IF;
  SELECT * INTO v_perfil FROM public.profiles p WHERE p.id = p_usuario_id FOR UPDATE;
  IF NOT FOUND OR v_perfil.role::text <> 'gestor' THEN
    RAISE EXCEPTION 'Perfil criado pelo convite nao esta no estado esperado' USING ERRCODE = '22023';
  END IF;
  UPDATE public.profiles SET nome_completo = trim(p_nome) WHERE id = p_usuario_id;

  IF p_tipo = 'super_admin' THEN
    IF COALESCE(pg_catalog.array_length(p_fundo_ids, 1), 0) > 0 THEN
      RAISE EXCEPTION 'Super Admin puro nao recebe fundos operacionais' USING ERRCODE = '22023';
    END IF;
    PERFORM pg_catalog.set_config('app.sa2_role_change', 'autorizado', true);
    UPDATE public.profiles SET role = 'super_admin'::public.user_role WHERE id = p_usuario_id;
    INSERT INTO public.usuario_papeis (usuario_id, papel, ativo, origem, atribuido_por, atribuido_em, revogado_em)
    VALUES (p_usuario_id, 'super_admin'::public.user_role, true, 'administracao', (SELECT auth.uid()), now(), NULL)
    ON CONFLICT (usuario_id, papel) DO UPDATE SET ativo = true, origem = 'administracao', atribuido_por = EXCLUDED.atribuido_por, atribuido_em = now(), revogado_em = NULL;
    PERFORM private.registrar_auditoria_usuario('SUPER_ADMIN_CONCEDIDO', p_usuario_id, NULL, NULL, jsonb_build_object('papel_primario', 'super_admin', 'convite', true), p_correlation_id);
  ELSE
    PERFORM private.registrar_auditoria_usuario('USUARIO_GESTOR_CONVIDADO', p_usuario_id, NULL, NULL, jsonb_build_object('papel_primario', 'gestor'), p_correlation_id);
    PERFORM public.admin_vincular_gestor_fundos(p_usuario_id, p_fundo_ids, p_correlation_id);
  END IF;
  RETURN public.admin_obter_usuario(p_usuario_id);
END;
$function$

CREATE OR REPLACE FUNCTION public.admin_resumo_usuarios()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_resultado jsonb;
BEGIN
  IF NOT (SELECT private.usuario_e_super_admin()) THEN
    RAISE EXCEPTION 'Acesso administrativo negado' USING ERRCODE = '42501';
  END IF;

  SELECT jsonb_build_object(
    'total', count(*),
    'ativos', count(*) FILTER (WHERE p.status::text = 'ativo'),
    'inativos', count(*) FILTER (WHERE p.status::text <> 'ativo'),
    'gestores', count(*) FILTER (WHERE p.role::text = 'gestor'),
    'super_admins', count(*) FILTER (WHERE EXISTS (
      SELECT 1 FROM public.usuario_papeis up
       WHERE up.usuario_id = p.id AND up.papel::text = 'super_admin' AND up.ativo IS TRUE
    ))
  ) INTO v_resultado
  FROM public.profiles p;

  RETURN v_resultado;
END;
$function$

CREATE OR REPLACE FUNCTION public.admin_revogar_gestor_fundo(p_usuario_id uuid, p_fundo_id uuid, p_correlation_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_vinculo public.usuario_fundos%ROWTYPE;
  v_antes jsonb;
BEGIN
  IF NOT (SELECT private.usuario_e_super_admin()) THEN RAISE EXCEPTION 'Acesso administrativo negado' USING ERRCODE = '42501'; END IF;
  SELECT * INTO v_vinculo FROM public.usuario_fundos uf
   WHERE uf.usuario_id = p_usuario_id AND uf.fundo_id = p_fundo_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Vinculo nao encontrado' USING ERRCODE = 'P0002'; END IF;
  IF v_vinculo.status = 'revogado' THEN RETURN jsonb_build_object('id', v_vinculo.id, 'status', v_vinculo.status, 'idempotente', true); END IF;
  v_antes := to_jsonb(v_vinculo);
  UPDATE public.usuario_fundos SET status = 'revogado', principal = false
   WHERE id = v_vinculo.id RETURNING * INTO v_vinculo;
  PERFORM private.registrar_auditoria_usuario('GESTOR_VINCULO_REVOGADO', p_usuario_id, p_fundo_id, v_antes, to_jsonb(v_vinculo), p_correlation_id);
  RETURN jsonb_build_object('id', v_vinculo.id, 'status', v_vinculo.status, 'idempotente', false);
END;
$function$

CREATE OR REPLACE FUNCTION public.admin_vincular_gestor_fundo(p_usuario_id uuid, p_fundo_id uuid, p_correlation_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_perfil public.profiles%ROWTYPE;
  v_vinculo public.usuario_fundos%ROWTYPE;
  v_antes jsonb;
  v_evento text;
BEGIN
  IF NOT (SELECT private.usuario_e_super_admin()) THEN RAISE EXCEPTION 'Acesso administrativo negado' USING ERRCODE = '42501'; END IF;
  -- Serializa o par usuario/fundo antes do SELECT para que duas abas
  -- concorrentes terminem no mesmo vinculo canonico, sem conflito UNIQUE.
  PERFORM pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(p_usuario_id::text || ':' || p_fundo_id::text, 82002612)
  );
  SELECT * INTO v_perfil FROM public.profiles p WHERE p.id = p_usuario_id FOR UPDATE;
  IF NOT FOUND OR v_perfil.role::text <> 'gestor' THEN RAISE EXCEPTION 'Usuario alvo nao possui papel Gestor' USING ERRCODE = '22023'; END IF;
  IF NOT EXISTS (SELECT 1 FROM public.fundos f WHERE f.id = p_fundo_id) THEN RAISE EXCEPTION 'Fundo nao encontrado' USING ERRCODE = 'P0002'; END IF;

  SELECT * INTO v_vinculo FROM public.usuario_fundos uf
   WHERE uf.usuario_id = p_usuario_id AND uf.fundo_id = p_fundo_id FOR UPDATE;
  IF FOUND THEN
    IF v_vinculo.status = 'ativo' THEN
      RETURN jsonb_build_object('id', v_vinculo.id, 'status', v_vinculo.status, 'idempotente', true);
    END IF;
    v_antes := to_jsonb(v_vinculo);
    UPDATE public.usuario_fundos SET status = 'ativo', perfil_no_fundo = 'gestor'
     WHERE id = v_vinculo.id RETURNING * INTO v_vinculo;
    v_evento := 'GESTOR_VINCULO_REATIVADO';
  ELSE
    v_antes := NULL;
    INSERT INTO public.usuario_fundos (usuario_id, fundo_id, perfil_no_fundo, status, principal)
    VALUES (p_usuario_id, p_fundo_id, 'gestor', 'ativo', false)
    RETURNING * INTO v_vinculo;
    v_evento := 'GESTOR_VINCULADO_FUNDO';
  END IF;
  PERFORM private.registrar_auditoria_usuario(v_evento, p_usuario_id, p_fundo_id, v_antes, to_jsonb(v_vinculo), p_correlation_id);
  RETURN jsonb_build_object('id', v_vinculo.id, 'status', v_vinculo.status, 'idempotente', false);
END;
$function$

CREATE OR REPLACE FUNCTION public.admin_vincular_gestor_fundos(p_usuario_id uuid, p_fundo_ids uuid[], p_correlation_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_fundo_id uuid;
  v_ids uuid[] := COALESCE(p_fundo_ids, ARRAY[]::uuid[]);
BEGIN
  IF NOT (SELECT private.usuario_e_super_admin()) THEN
    RAISE EXCEPTION 'Acesso administrativo negado' USING ERRCODE = '42501';
  END IF;
  IF pg_catalog.array_length(v_ids, 1) > 100 THEN
    RAISE EXCEPTION 'Quantidade de fundos acima do limite administrativo' USING ERRCODE = '22023';
  END IF;

  FOREACH v_fundo_id IN ARRAY v_ids LOOP
    PERFORM public.admin_vincular_gestor_fundo(p_usuario_id, v_fundo_id, p_correlation_id);
  END LOOP;

  RETURN public.admin_obter_usuario(p_usuario_id);
END;
$function$

CREATE OR REPLACE FUNCTION public.analisar_canhoto_documento(p_canhoto_id uuid, p_documento_versao_id uuid, p_resultado text, p_motivo text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  canhoto_row record;
  entrega record;
  novo_status text;
BEGIN
  IF auth.uid() IS NULL OR get_user_role() <> 'gestor' THEN
    RAISE EXCEPTION 'Somente gestor pode analisar canhoto';
  END IF;
  IF p_resultado NOT IN ('aprovado', 'rejeitado') THEN RAISE EXCEPTION 'Resultado invalido'; END IF;
  IF p_resultado = 'rejeitado' AND length(trim(coalesce(p_motivo, ''))) = 0 THEN RAISE EXCEPTION 'Motivo obrigatorio ao rejeitar'; END IF;

  SELECT * INTO canhoto_row FROM public.canhotos WHERE id = p_canhoto_id FOR UPDATE;
  IF canhoto_row.id IS NULL OR canhoto_row.documento_versao_atual_id <> p_documento_versao_id THEN
    RAISE EXCEPTION 'Versao documental nao corresponde ao canhoto';
  END IF;
  SELECT * INTO entrega FROM public.nota_fiscal_entregas WHERE id = canhoto_row.nota_fiscal_entrega_id FOR UPDATE;
  novo_status := CASE WHEN p_resultado = 'aprovado' THEN 'aprovado' ELSE 'rejeitado' END;

  INSERT INTO public.documento_analises (documento_versao_id, resultado, analisado_por, observacoes, dados_estruturados)
  VALUES (p_documento_versao_id, p_resultado, auth.uid(), p_motivo, '{}'::jsonb);

  UPDATE public.documento_versoes SET status = novo_status WHERE id = p_documento_versao_id;
  UPDATE public.documentos_repositorio SET status = novo_status WHERE id = canhoto_row.documento_id;
  UPDATE public.canhotos
  SET status = novo_status,
      analisado_por = auth.uid(),
      analisado_em = now(),
      motivo_rejeicao = CASE WHEN p_resultado = 'rejeitado' THEN p_motivo ELSE NULL END,
      documento_versao_aprovada_id = CASE WHEN p_resultado = 'aprovado' THEN p_documento_versao_id ELSE NULL END
  WHERE id = p_canhoto_id;

  IF p_resultado = 'aprovado' THEN
    UPDATE public.documento_requisito_instancias
    SET status = 'satisfeito', versao_aprovada_id = p_documento_versao_id, satisfeito_em = now()
    WHERE nota_fiscal_entrega_id = canhoto_row.nota_fiscal_entrega_id AND tipo_documento_codigo_snapshot = 'canhoto';
    PERFORM public.registrar_evento_entrega(canhoto_row.nota_fiscal_entrega_id, 'canhoto_aprovado', entrega.status_entrega, entrega.status_entrega, 'usuario', jsonb_build_object('canhoto_id', p_canhoto_id));
  ELSE
    PERFORM public.registrar_evento_entrega(canhoto_row.nota_fiscal_entrega_id, 'canhoto_rejeitado', entrega.status_entrega, entrega.status_entrega, 'usuario', jsonb_build_object('canhoto_id', p_canhoto_id, 'motivo', p_motivo));
  END IF;

  PERFORM public.avaliar_conclusao_entrega(canhoto_row.nota_fiscal_entrega_id);
  RETURN jsonb_build_object('canhoto_id', p_canhoto_id, 'status', novo_status);
END;
$function$

CREATE OR REPLACE FUNCTION public.analisar_cte_documento(p_cte_id uuid, p_documento_versao_id uuid, p_resultado text, p_motivo text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  cte_row record;
  novo_status text;
  nf record;
BEGIN
  IF auth.uid() IS NULL OR get_user_role() <> 'gestor' THEN
    RAISE EXCEPTION 'Somente gestor pode analisar CT-e';
  END IF;
  IF p_resultado NOT IN ('aprovado', 'rejeitado') THEN RAISE EXCEPTION 'Resultado invalido'; END IF;
  IF p_resultado = 'rejeitado' AND length(trim(coalesce(p_motivo, ''))) = 0 THEN RAISE EXCEPTION 'Motivo obrigatorio ao rejeitar'; END IF;

  SELECT * INTO cte_row FROM public.ctes WHERE id = p_cte_id FOR UPDATE;
  IF cte_row.id IS NULL OR cte_row.documento_versao_atual_id <> p_documento_versao_id THEN
    RAISE EXCEPTION 'Versao documental nao corresponde ao CT-e';
  END IF;

  novo_status := CASE WHEN p_resultado = 'aprovado' THEN 'aprovado' ELSE 'rejeitado' END;
  INSERT INTO public.documento_analises (documento_versao_id, resultado, analisado_por, observacoes, dados_estruturados)
  VALUES (p_documento_versao_id, p_resultado, auth.uid(), p_motivo, cte_row.dados_extraidos);

  UPDATE public.documento_versoes SET status = novo_status WHERE id = p_documento_versao_id;
  UPDATE public.documentos_repositorio SET status = novo_status WHERE id = cte_row.documento_id;
  UPDATE public.ctes
  SET status = novo_status,
      analisado_por = auth.uid(),
      analisado_em = now(),
      motivo_rejeicao = CASE WHEN p_resultado = 'rejeitado' THEN p_motivo ELSE NULL END,
      documento_versao_aprovada_id = CASE WHEN p_resultado = 'aprovado' THEN p_documento_versao_id ELSE NULL END
  WHERE id = p_cte_id;

  FOR nf IN
    SELECT nfe.id, nfe.status_entrega, nfe.nota_fiscal_id
    FROM public.cte_notas_fiscais cnf
    JOIN public.nota_fiscal_entregas nfe ON nfe.nota_fiscal_id = cnf.nota_fiscal_id
    WHERE cnf.cte_id = p_cte_id
  LOOP
    IF p_resultado = 'aprovado' THEN
      UPDATE public.documento_requisito_instancias
      SET status = 'satisfeito', versao_aprovada_id = p_documento_versao_id, satisfeito_em = now()
      WHERE nota_fiscal_entrega_id = nf.id AND tipo_documento_codigo_snapshot = 'cte';
      PERFORM public.registrar_evento_entrega(nf.id, 'cte_aprovado', nf.status_entrega, nf.status_entrega, 'usuario', jsonb_build_object('cte_id', p_cte_id));
    ELSE
      PERFORM public.registrar_evento_entrega(nf.id, 'cte_rejeitado', nf.status_entrega, nf.status_entrega, 'usuario', jsonb_build_object('cte_id', p_cte_id, 'motivo', p_motivo));
    END IF;
    PERFORM public.avaliar_conclusao_entrega(nf.id);
  END LOOP;

  RETURN jsonb_build_object('cte_id', p_cte_id, 'status', novo_status);
END;
$function$

CREATE OR REPLACE FUNCTION public.analisar_documento_versao(p_documento_versao_id uuid, p_resultado text, p_observacoes text DEFAULT NULL::text, p_dados_estruturados jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  version_row record;
  analysis_id uuid;
  new_status text;
  entrega_id uuid;
BEGIN
  IF auth.uid() IS NULL OR get_user_role() <> 'gestor' THEN RAISE EXCEPTION 'Somente gestor pode analisar documentos'; END IF;
  IF p_resultado NOT IN ('aprovado', 'rejeitado', 'pendente', 'requer_ajuste') THEN RAISE EXCEPTION 'Resultado de analise invalido'; END IF;
  IF p_resultado IN ('rejeitado', 'requer_ajuste') AND length(trim(coalesce(p_observacoes, ''))) = 0 THEN
    RAISE EXCEPTION 'Motivo obrigatorio para rejeicao ou ajuste';
  END IF;

  SELECT dv.*, dr.id AS repo_id
    INTO version_row
  FROM public.documento_versoes dv
  JOIN public.documentos_repositorio dr ON dr.id = dv.documento_id
  WHERE dv.id = p_documento_versao_id;

  IF version_row.id IS NULL THEN RAISE EXCEPTION 'Versao documental nao encontrada'; END IF;
  IF version_row.status = 'aprovado' AND p_resultado <> 'aprovado' THEN RAISE EXCEPTION 'Versao aprovada e imutavel'; END IF;

  INSERT INTO public.documento_analises (documento_versao_id, resultado, analisado_por, observacoes, dados_estruturados)
  VALUES (p_documento_versao_id, p_resultado, auth.uid(), p_observacoes, coalesce(p_dados_estruturados, '{}'::jsonb))
  RETURNING id INTO analysis_id;

  new_status := CASE WHEN p_resultado = 'aprovado' THEN 'aprovado' WHEN p_resultado = 'rejeitado' THEN 'rejeitado' ELSE 'em_analise' END;
  UPDATE public.documento_versoes SET status = new_status WHERE id = p_documento_versao_id;
  UPDATE public.documentos_repositorio SET status = new_status WHERE id = version_row.documento_id;

  IF p_resultado = 'aprovado' THEN
    UPDATE public.documento_requisito_instancias
    SET status = 'satisfeito', versao_aprovada_id = p_documento_versao_id, satisfeito_em = now()
    WHERE documento_id = version_row.documento_id;
  ELSE
    UPDATE public.documento_requisito_instancias
    SET status = 'pendente', versao_aprovada_id = NULL, satisfeito_em = NULL
    WHERE documento_id = version_row.documento_id;
  END IF;

  SELECT nota_fiscal_entrega_id
    INTO entrega_id
  FROM public.documento_vinculos
  WHERE documento_id = version_row.documento_id
    AND nota_fiscal_entrega_id IS NOT NULL
  LIMIT 1;

  IF entrega_id IS NOT NULL THEN
    PERFORM public.avaliar_conclusao_entrega(entrega_id);
  END IF;

  RETURN jsonb_build_object('analise_id', analysis_id, 'versao_id', p_documento_versao_id, 'status', new_status, 'nota_fiscal_entrega_id', entrega_id);
END;
$function$

CREATE OR REPLACE FUNCTION public.aprovar_operacao_atomica(p_operacao_id uuid, p_taxa_desconto numeric)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  actor_id uuid := auth.uid();
  actor_role text := public.get_user_role();
  operacao_status text;
  fundo_id_operacao uuid;
BEGIN
  IF actor_id IS NULL OR actor_role <> 'gestor' THEN
    RAISE EXCEPTION 'Somente gestor autenticado pode aprovar operacao';
  END IF;

  IF p_taxa_desconto IS NULL OR p_taxa_desconto < 0 THEN
    RAISE EXCEPTION 'Taxa mensal invalida';
  END IF;

  SELECT o.status, cf.fundo_id
  INTO operacao_status, fundo_id_operacao
  FROM public.operacoes o
  JOIN public.cedente_fundos cf ON cf.id = o.cedente_fundo_id
  WHERE o.id = p_operacao_id
  FOR UPDATE OF o;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Operacao nao encontrada';
  END IF;

  IF NOT private.usuario_tem_acesso_fundo(fundo_id_operacao) THEN
    RAISE EXCEPTION 'Gestor sem acesso ao fundo da operacao';
  END IF;

  IF operacao_status = 'aprovada' THEN
    RAISE EXCEPTION 'A operacao ja foi aprovada e nao pode ser aprovada novamente';
  END IF;

  IF operacao_status NOT IN ('solicitada', 'em_analise') THEN
    RAISE EXCEPTION 'Operacao com status % nao pode ser aprovada', operacao_status;
  END IF;

  RETURN public.aprovar_operacao_atomica_financeiro_v1(
    p_operacao_id,
    p_taxa_desconto
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.aprovar_operacao_atomica(p_operacao_id uuid, p_taxa_desconto numeric, p_valor_liquido_desembolso numeric)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  actor_id uuid := auth.uid();
  actor_role text := public.get_user_role();
  op record;
  nf record;
  prazo_dias_nf integer;
  fator numeric;
  base_nf numeric;
  valor_antecipado_nf numeric;
  soma_base numeric := 0;
  prazo_ponderado numeric := 0;
  prazo_medio integer := 0;
  nfs_count integer := 0;
BEGIN
  IF actor_id IS NULL THEN
    RAISE EXCEPTION 'Usuario nao autenticado';
  END IF;

  IF actor_role <> 'gestor' THEN
    RAISE EXCEPTION 'Somente gestor pode aprovar operacao';
  END IF;

  IF p_taxa_desconto < 0 THEN
    RAISE EXCEPTION 'Taxa deve ser maior ou igual a zero';
  END IF;

  IF p_valor_liquido_desembolso <= 0 THEN
    RAISE EXCEPTION 'Valor liquido deve ser maior que zero';
  END IF;

  SELECT * INTO op
  FROM public.operacoes
  WHERE id = p_operacao_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Operacao nao encontrada';
  END IF;

  IF op.status = 'aprovada' THEN
    RETURN jsonb_build_object(
      'operacao_id', p_operacao_id,
      'idempotent_replay', true,
      'status', op.status,
      'prazo_dias', op.prazo_dias
    );
  END IF;

  IF op.status NOT IN ('solicitada', 'em_analise') THEN
    RAISE EXCEPTION 'Operacao com status "%" nao pode ser aprovada', op.status;
  END IF;

  IF op.contexto_configuracao_status = 'completo'
     AND (
       op.cedente_fundo_id IS NULL
       OR op.politica_operacional_id IS NULL
       OR op.politica_operacional_versao_id IS NULL
       OR op.politica_snapshot IS NULL
     ) THEN
    RAISE EXCEPTION 'Operacao sem contexto operacional completo';
  END IF;

  FOR nf IN
    SELECT n.*
    FROM public.operacoes_nfs onf
    JOIN public.notas_fiscais n ON n.id = onf.nota_fiscal_id
    WHERE onf.operacao_id = p_operacao_id
    ORDER BY n.id
    FOR UPDATE OF n
  LOOP
    IF nf.cedente_id <> op.cedente_id THEN
      RAISE EXCEPTION 'NF fora do cedente da operacao';
    END IF;

    IF op.cedente_fundo_id IS NOT NULL AND nf.cedente_fundo_id IS DISTINCT FROM op.cedente_fundo_id THEN
      RAISE EXCEPTION 'NF fora do vinculo cedente-fundo da operacao';
    END IF;

    IF nf.status NOT IN ('em_antecipacao', 'aceita') THEN
      RAISE EXCEPTION 'NF % nao esta elegivel para aprovacao', nf.numero_nf;
    END IF;

    prazo_dias_nf := greatest(1, ceil(extract(epoch FROM (nf.data_vencimento::timestamp - now()::timestamp)) / 86400.0)::integer);
    base_nf := coalesce(nf.valor_liquido, nf.valor_bruto);
    fator := power(1 + (p_taxa_desconto / 100), prazo_dias_nf::numeric / 30);
    valor_antecipado_nf := round((base_nf / fator)::numeric, 2);

    soma_base := soma_base + base_nf;
    prazo_ponderado := prazo_ponderado + (prazo_dias_nf * base_nf);
    nfs_count := nfs_count + 1;

    UPDATE public.notas_fiscais
    SET taxa_desagio = p_taxa_desconto,
        valor_antecipado = valor_antecipado_nf
    WHERE id = nf.id;
  END LOOP;

  IF nfs_count = 0 THEN
    RAISE EXCEPTION 'Operacao sem NFs vinculadas';
  END IF;

  IF soma_base > 0 THEN
    prazo_medio := round(prazo_ponderado / soma_base);
  END IF;

  UPDATE public.operacoes
  SET taxa_desconto = p_taxa_desconto,
      prazo_dias = prazo_medio,
      valor_liquido_desembolso = p_valor_liquido_desembolso,
      status = 'aprovada',
      aprovado_por = actor_id,
      aprovado_em = now()
  WHERE id = p_operacao_id;

  INSERT INTO public.logs_auditoria (
    usuario_id,
    tipo_evento,
    entidade_tipo,
    entidade_id,
    dados_antes,
    dados_depois
  )
  VALUES (
    actor_id,
    'OPERACAO_APROVADA',
    'operacoes',
    p_operacao_id,
    jsonb_build_object('status', op.status),
    jsonb_build_object(
      'status', 'aprovada',
      'taxa_desconto', p_taxa_desconto,
      'prazo_dias', prazo_medio,
      'valor_liquido_desembolso', p_valor_liquido_desembolso,
      'nfs', nfs_count
    )
  );

  RETURN jsonb_build_object(
    'operacao_id', p_operacao_id,
    'idempotent_replay', false,
    'status', 'aprovada',
    'prazo_dias', prazo_medio,
    'nfs', nfs_count
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.aprovar_operacao_atomica_financeiro_v1(p_operacao_id uuid, p_taxa_desconto numeric)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  actor_id uuid := auth.uid();
  actor_role text := public.get_user_role();
  op record;
  nf record;
  memoria jsonb;
  metodo text;
  data_base date := (pg_catalog.timezone('America/Sao_Paulo', pg_catalog.now()))::date;
  fundo_id_operacao uuid;
  v_valor_bruto_total numeric := 0;
  valor_liquido_total numeric := 0;
  desconto_total numeric := 0;
  prazo_ponderado numeric := 0;
  prazo_medio integer := 0;
  prazo_referencia integer := 0;
  vencimento_maximo date;
  nfs_count integer := 0;
BEGIN
  IF actor_id IS NULL OR actor_role <> 'gestor' THEN
    RAISE EXCEPTION 'Somente gestor autenticado pode aprovar operacao';
  END IF;
  IF p_taxa_desconto IS NULL OR p_taxa_desconto < 0 THEN
    RAISE EXCEPTION 'Taxa mensal invalida';
  END IF;

  SELECT o.*, cf.fundo_id
  INTO op
  FROM public.operacoes o
  JOIN public.cedente_fundos cf ON cf.id = o.cedente_fundo_id
  WHERE o.id = p_operacao_id
  FOR UPDATE OF o;

  IF NOT FOUND THEN RAISE EXCEPTION 'Operacao nao encontrada'; END IF;
  fundo_id_operacao := op.fundo_id;
  IF NOT private.usuario_tem_acesso_fundo(fundo_id_operacao) THEN
    RAISE EXCEPTION 'Gestor sem acesso ao fundo da operacao';
  END IF;

  IF op.status = 'aprovada' THEN
    RETURN jsonb_build_object(
      'operacao_id', op.id,
      'idempotent_replay', true,
      'status', op.status,
      'valor_liquido_desembolso', op.valor_liquido_desembolso,
      'metodo_calculo_financeiro', coalesce(op.metodo_calculo_financeiro, 'LEGADO_MENSAL_DIAS_REAIS_30'),
      'data_base', op.calculo_data_base
    );
  END IF;
  IF op.status NOT IN ('solicitada', 'em_analise') THEN
    RAISE EXCEPTION 'Operacao com status % nao pode ser aprovada', op.status;
  END IF;
  IF op.contexto_configuracao_status = 'completo' AND (
    op.cedente_fundo_id IS NULL OR op.politica_operacional_versao_id IS NULL OR op.politica_snapshot IS NULL
  ) THEN
    RAISE EXCEPTION 'Operacao sem contexto operacional completo';
  END IF;

  metodo := coalesce(
    op.metodo_calculo_financeiro,
    op.politica_snapshot #>> '{calculo_financeiro,metodo}',
    'LEGADO_MENSAL_DIAS_REAIS_30'
  );
  IF metodo NOT IN ('LEGADO_MENSAL_DIAS_REAIS_30', 'DIAS_UTEIS_252', 'TRINTA_360', 'DIAS_CORRIDOS_365') THEN
    RAISE EXCEPTION 'Metodo financeiro congelado na operacao e invalido';
  END IF;

  DELETE FROM public.operacao_calculo_nfs WHERE operacao_id = p_operacao_id;

  FOR nf IN
    SELECT n.*
    FROM public.operacoes_nfs onf
    JOIN public.notas_fiscais n ON n.id = onf.nota_fiscal_id
    WHERE onf.operacao_id = p_operacao_id
    ORDER BY n.id
    FOR UPDATE OF n
  LOOP
    IF nf.cedente_id <> op.cedente_id
       OR nf.cedente_fundo_id IS DISTINCT FROM op.cedente_fundo_id
       OR nf.fundo_id IS DISTINCT FROM fundo_id_operacao THEN
      RAISE EXCEPTION 'NF fora do contexto da operacao';
    END IF;
    IF nf.status NOT IN ('em_antecipacao', 'aceita') THEN
      RAISE EXCEPTION 'NF % nao esta elegivel para aprovacao', nf.numero_nf;
    END IF;

    memoria := private.calcular_memoria_financeira_nf(
      nf.id, nf.valor_bruto, p_taxa_desconto, data_base, nf.data_vencimento, metodo
    );

    INSERT INTO public.operacao_calculo_nfs (
      operacao_id, nota_fiscal_id, fundo_id, cedente_id, metodo_calculo_financeiro,
      valor_nominal, taxa_mensal, data_base, vencimento_contratual, vencimento_calculo,
      base_calculo, calendario, dias_corridos_reais, dias_uteis, dias_financeiros,
      dias_aplicados, expoente, fator, valor_presente, desconto, regra_arredondamento, versao_motor
    ) VALUES (
      op.id, nf.id, fundo_id_operacao, op.cedente_id, metodo,
      (memoria->>'valor_nominal')::numeric, p_taxa_desconto, data_base,
      (memoria->>'vencimento_contratual')::date, (memoria->>'vencimento_calculo')::date,
      (memoria->>'base')::integer, memoria->>'calendario',
      (memoria->>'dias_corridos_reais')::integer, (memoria->>'dias_uteis')::integer,
      (memoria->>'dias_financeiros')::integer, (memoria->>'dias')::integer,
      (memoria->>'expoente')::numeric, (memoria->>'fator')::numeric,
      (memoria->>'valor_presente')::numeric, (memoria->>'desconto')::numeric,
      memoria->>'arredondamento', (memoria->>'versao_motor')::integer
    );

    UPDATE public.notas_fiscais
    SET taxa_desagio = p_taxa_desconto,
        valor_antecipado = (memoria->>'valor_presente')::numeric
    WHERE id = nf.id;

    v_valor_bruto_total := v_valor_bruto_total + (memoria->>'valor_nominal')::numeric;
    valor_liquido_total := valor_liquido_total + (memoria->>'valor_presente')::numeric;
    desconto_total := desconto_total + (memoria->>'desconto')::numeric;
    prazo_ponderado := prazo_ponderado + ((memoria->>'dias')::integer * (memoria->>'valor_nominal')::numeric);
    prazo_referencia := greatest(prazo_referencia, (memoria->>'dias')::integer);
    vencimento_maximo := greatest(vencimento_maximo, nf.data_vencimento);
    nfs_count := nfs_count + 1;
  END LOOP;

  IF nfs_count = 0 THEN RAISE EXCEPTION 'Operacao sem NFs vinculadas'; END IF;

  IF NOT EXISTS (
    SELECT 1 FROM public.taxas_cedente tc
    WHERE tc.cedente_id = op.cedente_id
      AND tc.taxa_percentual = p_taxa_desconto
      AND prazo_referencia BETWEEN tc.prazo_min AND tc.prazo_max
  ) THEN
    RAISE EXCEPTION 'A taxa selecionada nao esta configurada para o prazo da operacao';
  END IF;

  prazo_medio := round(prazo_ponderado / v_valor_bruto_total);

  PERFORM pg_catalog.set_config('app.calculo_aprovacao', 'true', true);

  UPDATE public.operacoes
  SET taxa_desconto = p_taxa_desconto,
      prazo_dias = prazo_medio,
      valor_bruto_total = round(v_valor_bruto_total, 2),
      valor_liquido_desembolso = round(valor_liquido_total, 2),
      data_vencimento = vencimento_maximo,
      metodo_calculo_financeiro = metodo,
      calculo_data_base = data_base,
      calculo_versao_motor = 1,
      calculo_memoria = jsonb_build_object(
        'metodo', metodo,
        'taxa_mensal', p_taxa_desconto,
        'data_base', data_base,
        'valor_bruto_total', round(v_valor_bruto_total, 2),
        'valor_liquido_total', round(valor_liquido_total, 2),
        'desconto_total', round(desconto_total, 2),
        'prazo_medio', prazo_medio,
        'prazo_unidade', CASE metodo
          WHEN 'DIAS_UTEIS_252' THEN 'dias_uteis'
          WHEN 'TRINTA_360' THEN 'dias_financeiros'
          ELSE 'dias_corridos'
        END,
        'vencimento_maximo', vencimento_maximo,
        'quantidade_nfs', nfs_count,
        'previa_valor_liquido_solicitacao', op.valor_liquido_desembolso,
        'diferenca_previa_aprovacao', CASE
          WHEN op.valor_liquido_desembolso IS NULL THEN NULL
          ELSE round(valor_liquido_total - op.valor_liquido_desembolso, 2)
        END,
        'versao_motor', 1,
        'arredondamento', 'ROUND_HALF_UP_2_CASAS'
      ),
      status = 'aprovada',
      aprovado_por = actor_id,
      aprovado_em = now()
  WHERE id = p_operacao_id AND status IN ('solicitada', 'em_analise');

  IF NOT FOUND THEN RAISE EXCEPTION 'A operacao foi alterada concorrentemente'; END IF;

  INSERT INTO public.logs_auditoria (
    usuario_id, tipo_evento, entidade_tipo, entidade_id, dados_antes, dados_depois
  ) VALUES (
    actor_id, 'OPERACAO_APROVADA', 'operacoes', p_operacao_id,
    jsonb_build_object('status', op.status),
    jsonb_build_object(
      'status', 'aprovada', 'taxa_desconto', p_taxa_desconto,
      'metodo_calculo_financeiro', metodo, 'data_base', data_base,
      'prazo_dias', prazo_medio, 'valor_liquido_desembolso', round(valor_liquido_total, 2),
      'desconto_total', round(desconto_total, 2), 'nfs', nfs_count
    )
  );

  RETURN jsonb_build_object(
    'operacao_id', p_operacao_id,
    'idempotent_replay', false,
    'status', 'aprovada',
    'prazo_dias', prazo_medio,
    'valor_liquido_desembolso', round(valor_liquido_total, 2),
    'desconto_total', round(desconto_total, 2),
    'metodo_calculo_financeiro', metodo,
    'data_base', data_base,
    'nfs', nfs_count
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.aprovar_operacao_com_risco_atomica(p_operacao_id uuid, p_taxa_desconto numeric, p_risco_execucao_id uuid, p_assinatura_inputs text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE v_op record; v_risco public.risco_execucoes%ROWTYPE; v_revisao public.risco_revisoes%ROWTYPE; v_result jsonb;
BEGIN
  IF auth.uid() IS NULL OR (
    public.get_user_role()::text<>'gestor'
    AND NOT EXISTS(SELECT 1 FROM public.usuario_papeis up WHERE up.usuario_id=auth.uid() AND up.papel::text='gestor' AND up.ativo)
  ) THEN RAISE EXCEPTION 'Somente gestor autenticado pode aprovar operacao'; END IF;
  PERFORM pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended('aprovar-risco:'||p_operacao_id::text,0));
  SELECT o.*,cf.fundo_id INTO v_op FROM public.operacoes o JOIN public.cedente_fundos cf ON cf.id=o.cedente_fundo_id WHERE o.id=p_operacao_id FOR UPDATE OF o;
  IF NOT FOUND OR v_op.status NOT IN ('solicitada','em_analise') THEN RAISE EXCEPTION 'Operacao nao elegivel ou alterada concorrentemente'; END IF;
  IF NOT private.financeiro_gestor_tem_acesso_fundo(v_op.fundo_id) THEN RAISE EXCEPTION 'Gestor sem acesso ao fundo da operacao'; END IF;
  SELECT * INTO v_risco FROM public.risco_execucoes WHERE id=p_risco_execucao_id AND operacao_id=p_operacao_id AND fundo_id=v_op.fundo_id;
  IF NOT FOUND OR v_risco.assinatura_inputs<>p_assinatura_inputs OR v_risco.regra_versao<>'GATE_RISCO_V1' THEN RAISE EXCEPTION 'Avaliacao de risco invalida para a operacao'; END IF;
  IF v_risco.operacao_updated_at_snapshot IS DISTINCT FROM v_op.updated_at OR v_risco.taxa_desconto_snapshot IS DISTINCT FROM p_taxa_desconto THEN RAISE EXCEPTION 'A avaliacao de risco expirou porque a operacao foi alterada'; END IF;
  IF v_risco.aplicavel AND v_risco.decisao='BLOQUEADO' THEN RAISE EXCEPTION 'Operacao bloqueada pelo gate de risco'; END IF;
  IF v_risco.aplicavel AND v_risco.decisao='REVISAO_MANUAL' THEN
    SELECT * INTO v_revisao FROM public.risco_revisoes WHERE risco_execucao_id=v_risco.id AND assinatura_inputs=v_risco.assinatura_inputs;
    IF NOT FOUND OR v_revisao.status<>'LIBERADA' THEN RAISE EXCEPTION 'Operacao depende de revisao manual liberada'; END IF;
  ELSIF v_risco.aplicavel AND v_risco.decisao<>'APTO' THEN RAISE EXCEPTION 'Decisao de risco nao autoriza aprovacao'; END IF;
  v_result:=public.aprovar_operacao_atomica_financeiro_v1(p_operacao_id,p_taxa_desconto);
  UPDATE public.operacoes SET risco_execucao_id=v_risco.id,risco_revisao_id=v_revisao.id,
    risco_decisao_snapshot=CASE WHEN v_risco.aplicavel THEN v_risco.decisao ELSE 'NAO_APLICAVEL' END,
    risco_assinatura_inputs=v_risco.assinatura_inputs,risco_avaliado_em=v_risco.finalizado_em WHERE id=p_operacao_id;
  RETURN v_result||pg_catalog.jsonb_build_object('risco_execucao_id',v_risco.id,'risco_decisao',CASE WHEN v_risco.aplicavel THEN v_risco.decisao ELSE 'NAO_APLICAVEL' END);
END; $function$

CREATE OR REPLACE FUNCTION public.avaliar_gate_logistico_pre_cessao_nfs(p_nota_fiscal_ids uuid[])
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  actor_id uuid := auth.uid();
  actor_role text := public.get_user_role();
  nf record;
  v_politica_versao_id uuid;
  v_gate boolean;
  v_classificacao jsonb;
  v_resultado jsonb := '[]'::jsonb;
BEGIN
  IF actor_id IS NULL OR actor_role NOT IN ('cedente', 'gestor') THEN
    RAISE EXCEPTION 'Usuario sem permissao para avaliar gate logistico' USING ERRCODE = '42501';
  END IF;
  IF p_nota_fiscal_ids IS NULL OR cardinality(p_nota_fiscal_ids) = 0 THEN RETURN v_resultado; END IF;

  FOR nf IN
    SELECT n.id, n.cedente_id, n.fundo_id
    FROM public.notas_fiscais n
    WHERE n.id = ANY(p_nota_fiscal_ids)
    ORDER BY n.id
  LOOP
    IF actor_role = 'cedente' AND nf.cedente_id IS DISTINCT FROM public.get_user_cedente_id() THEN
      RAISE EXCEPTION 'NF fora do cedente autenticado' USING ERRCODE = '42501';
    END IF;
    IF actor_role = 'gestor' AND NOT private.usuario_tem_acesso_fundo(nf.fundo_id) THEN
      RAISE EXCEPTION 'Gestor sem acesso ao fundo da NF' USING ERRCODE = '42501';
    END IF;

    v_politica_versao_id := private.resolver_politica_versao_nf_logistica(nf.id);
    SELECT coalesce(pov.exigir_status_logistico_pre_cessao, false)
    INTO v_gate
    FROM public.politica_operacional_versoes pov
    WHERE pov.id = v_politica_versao_id;
    v_classificacao := private.classificar_status_logistico_pre_cessao(nf.id, v_politica_versao_id);
    v_resultado := v_resultado || jsonb_build_array(jsonb_build_object(
      'nota_fiscal_id', nf.id,
      'politica_operacional_versao_id', v_politica_versao_id,
      'gate_exigido', coalesce(v_gate, false),
      'status', coalesce(v_classificacao->>'status', 'INDETERMINADA'),
      'permitido', NOT coalesce(v_gate, false) OR coalesce(v_classificacao->>'status', 'INDETERMINADA') <> 'INDETERMINADA'
    ));
  END LOOP;

  IF jsonb_array_length(v_resultado) <> (
    SELECT count(DISTINCT id) FROM unnest(p_nota_fiscal_ids) ids(id)
  ) THEN
    RAISE EXCEPTION 'Uma ou mais NFs nao foram encontradas';
  END IF;
  RETURN v_resultado;
END;
$function$

CREATE OR REPLACE FUNCTION public.comunicar_postergacao_upload_canhoto(p_nota_fiscal_id uuid, p_nova_previsao date, p_motivo text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_usuario_id uuid := auth.uid();
  v_role text;
  v_cedente_autenticado_id uuid;
  v_entrega public.nota_fiscal_entregas%ROWTYPE;
  v_nf public.notas_fiscais%ROWTYPE;
  v_operacao public.operacoes%ROWTYPE;
  v_vinculo public.cedente_fundos%ROWTYPE;
  v_perfil public.profiles%ROWTYPE;
  v_snapshot jsonb;
  v_requer_canhoto boolean := false;
  v_permite boolean := false;
  v_limite integer;
  v_prazo_original date;
  v_data_minima date;
  v_data_maxima date;
  v_motivo text := btrim(COALESCE(p_motivo, ''));
  v_primeiro_upload_em timestamptz;
  v_postergacao public.nota_fiscal_entrega_postergacoes_canhoto%ROWTYPE;
BEGIN
  IF v_usuario_id IS NULL THEN
    RAISE EXCEPTION 'Usuario nao autenticado.' USING ERRCODE = '42501';
  END IF;

  v_role := public.get_user_role()::text;
  IF v_role <> 'cedente' THEN
    RAISE EXCEPTION 'Somente o cedente pode informar nova previsao de upload do canhoto.' USING ERRCODE = '42501';
  END IF;

  v_cedente_autenticado_id := public.get_user_cedente_id();
  IF v_cedente_autenticado_id IS NULL THEN
    RAISE EXCEPTION 'Cedente autenticado nao encontrado.' USING ERRCODE = '42501';
  END IF;

  IF p_nota_fiscal_id IS NULL OR p_nova_previsao IS NULL THEN
    RAISE EXCEPTION 'Nota fiscal e nova previsao sao obrigatorias.' USING ERRCODE = '22023';
  END IF;

  IF length(v_motivo) = 0 OR length(v_motivo) > 1000 THEN
    RAISE EXCEPTION 'Informe o motivo da nova previsao com ate 1000 caracteres.' USING ERRCODE = '22023';
  END IF;

  SELECT nf.* INTO v_nf
  FROM public.notas_fiscais nf
  WHERE nf.id = p_nota_fiscal_id;

  IF v_nf.id IS NULL OR v_nf.cedente_id <> v_cedente_autenticado_id THEN
    RAISE EXCEPTION 'Nota fiscal nao encontrada para o cedente autenticado.' USING ERRCODE = '42501';
  END IF;

  IF v_nf.fundo_id IS NULL OR v_nf.cedente_fundo_id IS NULL THEN
    RAISE EXCEPTION 'A nota fiscal nao possui contexto de fundo completo.' USING ERRCODE = '22023';
  END IF;

  SELECT cf.* INTO v_vinculo
  FROM public.cedente_fundos cf
  WHERE cf.id = v_nf.cedente_fundo_id
    AND cf.cedente_id = v_nf.cedente_id
    AND cf.fundo_id = v_nf.fundo_id
    AND cf.status = 'ativo';

  IF v_vinculo.id IS NULL THEN
    RAISE EXCEPTION 'O vinculo cedente-fundo da nota fiscal nao esta ativo.' USING ERRCODE = '42501';
  END IF;

  SELECT nfe.* INTO v_entrega
  FROM public.nota_fiscal_entregas nfe
  WHERE nfe.nota_fiscal_id = p_nota_fiscal_id
    AND nfe.status_entrega <> 'nao_aplicavel'
  ORDER BY nfe.created_at DESC
  LIMIT 1
  FOR UPDATE;

  IF v_entrega.id IS NULL OR v_entrega.cessao_efetivada_em IS NULL THEN
    RAISE EXCEPTION 'A postergação so pode ser informada apos a cessao da nota fiscal.' USING ERRCODE = '22023';
  END IF;

  SELECT o.* INTO v_operacao
  FROM public.operacoes o
  WHERE o.id = v_entrega.operacao_id;

  IF v_operacao.id IS NULL
     OR v_operacao.cedente_id <> v_nf.cedente_id
     OR v_operacao.cedente_fundo_id IS DISTINCT FROM v_nf.cedente_fundo_id THEN
    RAISE EXCEPTION 'Contexto operacional da entrega e invalido.' USING ERRCODE = '22023';
  END IF;

  v_snapshot := v_operacao.politica_snapshot;
  IF v_snapshot IS NULL OR v_operacao.politica_operacional_versao_id IS NULL OR v_operacao.politica_snapshot_hash IS NULL THEN
    RAISE EXCEPTION 'A operacao nao possui snapshot de politica compativel com a postergacao.' USING ERRCODE = '22023';
  END IF;

  SELECT EXISTS (
    SELECT 1
    FROM jsonb_array_elements(COALESCE(v_snapshot->'requisitos', '[]'::jsonb)) requisito
    WHERE COALESCE((requisito->>'ativo')::boolean, false)
      AND COALESCE((requisito->>'obrigatorio')::boolean, false)
      AND COALESCE(requisito->>'escopo', '') IN ('pos_cessao', 'entrega')
      AND lower(regexp_replace(
        COALESCE(requisito->>'tipo_documento_codigo', requisito->>'codigo', ''),
        '[^a-zA-Z0-9]+', '_', 'g'
      )) IN ('canhoto', 'comprovante_entrega')
  ) INTO v_requer_canhoto;

  IF NOT v_requer_canhoto THEN
    RAISE EXCEPTION 'O snapshot da operacao nao exige canhoto no pos-cessao.' USING ERRCODE = '22023';
  END IF;

  v_permite := lower(COALESCE(v_snapshot->>'permite_postergacao_upload_canhoto', 'false')) = 'true';
  IF NOT v_permite THEN
    RAISE EXCEPTION 'A politica registrada na operacao nao permite postergacao do upload do canhoto.' USING ERRCODE = '22023';
  END IF;

  BEGIN
    v_limite := NULLIF(v_snapshot->>'limite_postergacao_upload_canhoto_dias', '')::integer;
  EXCEPTION WHEN invalid_text_representation OR numeric_value_out_of_range THEN
    RAISE EXCEPTION 'O snapshot da operacao possui limite de postergacao invalido.' USING ERRCODE = '22023';
  END;
  v_limite := COALESCE(v_limite, 5);
  IF v_limite <= 0 THEN
    RAISE EXCEPTION 'O limite de postergacao registrado na operacao e invalido.' USING ERRCODE = '22023';
  END IF;

  v_prazo_original := v_entrega.data_limite_canhoto;
  IF v_prazo_original IS NULL THEN
    RAISE EXCEPTION 'A entrega nao possui prazo original de upload do canhoto.' USING ERRCODE = '22023';
  END IF;

  v_data_maxima := v_prazo_original + v_limite;
  v_data_minima := GREATEST(CURRENT_DATE, v_prazo_original + 1);

  IF CURRENT_DATE > v_data_maxima THEN
    RAISE EXCEPTION 'O prazo maximo para comunicar a nova previsao ja foi ultrapassado.' USING ERRCODE = '22023';
  END IF;

  IF p_nova_previsao <= v_prazo_original THEN
    RAISE EXCEPTION 'A nova previsao deve ser posterior ao prazo original.' USING ERRCODE = '22023';
  END IF;

  IF p_nova_previsao < CURRENT_DATE THEN
    RAISE EXCEPTION 'A nova previsao nao pode estar no passado.' USING ERRCODE = '22023';
  END IF;

  IF p_nova_previsao < v_data_minima OR p_nova_previsao > v_data_maxima THEN
    RAISE EXCEPTION 'A nova previsao deve estar entre % e %.', v_data_minima, v_data_maxima USING ERRCODE = '22023';
  END IF;

  IF EXISTS (
    SELECT 1
    FROM public.nota_fiscal_entrega_postergacoes_canhoto p
    WHERE p.nota_fiscal_id = p_nota_fiscal_id
  ) THEN
    RAISE EXCEPTION 'A nova previsao de upload do canhoto ja foi informada para esta nota fiscal.' USING ERRCODE = '23505';
  END IF;

  SELECT MIN(dv.created_at) INTO v_primeiro_upload_em
  FROM public.documento_requisito_instancias dri
  JOIN public.documento_versoes dv ON dv.documento_id = dri.documento_id
  WHERE dri.nota_fiscal_entrega_id = v_entrega.id
    AND lower(regexp_replace(COALESCE(dri.tipo_documento_codigo_snapshot, ''), '[^a-zA-Z0-9]+', '_', 'g'))
      IN ('canhoto', 'comprovante_entrega');

  IF v_primeiro_upload_em IS NULL THEN
    SELECT MIN(c.created_at) INTO v_primeiro_upload_em
    FROM public.canhotos c
    WHERE c.nota_fiscal_entrega_id = v_entrega.id;
  END IF;

  IF v_primeiro_upload_em IS NOT NULL THEN
    RAISE EXCEPTION 'A nova previsao nao pode ser informada depois do primeiro upload do canhoto.' USING ERRCODE = '22023';
  END IF;

  SELECT p.* INTO v_perfil
  FROM public.profiles p
  WHERE p.id = v_usuario_id;

  INSERT INTO public.nota_fiscal_entrega_postergacoes_canhoto (
    nota_fiscal_entrega_id,
    nota_fiscal_id,
    operacao_id,
    fundo_id,
    cedente_id,
    cedente_fundo_id,
    politica_operacional_versao_id,
    politica_snapshot_hash,
    prazo_original_upload_canhoto,
    nova_previsao_upload_canhoto,
    motivo_postergacao,
    limite_postergacao_dias_aplicado,
    postergacao_comunicada_por
  ) VALUES (
    v_entrega.id,
    v_nf.id,
    v_operacao.id,
    v_nf.fundo_id,
    v_nf.cedente_id,
    v_nf.cedente_fundo_id,
    v_operacao.politica_operacional_versao_id,
    v_operacao.politica_snapshot_hash,
    v_prazo_original,
    p_nova_previsao,
    v_motivo,
    v_limite,
    v_usuario_id
  )
  RETURNING * INTO v_postergacao;

  INSERT INTO public.eventos_entrega (
    nota_fiscal_entrega_id,
    tipo_evento,
    status_anterior,
    status_novo,
    registrado_por,
    ator_tipo,
    dados
  ) VALUES (
    v_entrega.id,
    'canhoto_postergacao_comunicada',
    v_entrega.status_entrega,
    v_entrega.status_entrega,
    v_usuario_id,
    'usuario',
    jsonb_build_object(
      'nota_fiscal_id', v_nf.id,
      'operacao_id', v_operacao.id,
      'fundo_id', v_nf.fundo_id,
      'cedente_id', v_nf.cedente_id,
      'cedente_fundo_id', v_nf.cedente_fundo_id,
      'prazo_original_upload_canhoto', v_prazo_original,
      'nova_previsao_upload_canhoto', p_nova_previsao,
      'motivo_postergacao', v_motivo,
      'limite_postergacao_dias_aplicado', v_limite,
      'politica_operacional_versao_id', v_operacao.politica_operacional_versao_id,
      'politica_snapshot_hash', v_operacao.politica_snapshot_hash,
      'dispensa_aprovacao_gestor', true,
      'ator_usuario_id', v_usuario_id,
      'ator_perfil', v_role
    )
  );

  INSERT INTO public.eventos_dominio (
    tenant_id,
    fundo_id,
    cedente_id,
    cedente_fundo_id,
    nota_fiscal_id,
    operacao_id,
    tipo_evento,
    categoria,
    ator_usuario_id,
    ator_nome_snapshot,
    ator_perfil_snapshot,
    origem,
    descricao,
    metadata,
    visibilidade,
    origem_evento,
    origem_registro_id
  ) VALUES (
    v_nf.fundo_id,
    v_nf.fundo_id,
    v_nf.cedente_id,
    v_nf.cedente_fundo_id,
    v_nf.id,
    v_operacao.id,
    'canhoto_postergacao_comunicada',
    'logistica',
    v_usuario_id,
    COALESCE(NULLIF(v_perfil.nome_completo, ''), NULLIF(v_perfil.email, ''), 'Cedente'),
    v_role,
    'rpc',
    'Cedente informou nova previsao de upload do canhoto.',
    jsonb_build_object(
      'nota_fiscal_entrega_id', v_entrega.id,
      'prazo_original_upload_canhoto', v_prazo_original,
      'nova_previsao_upload_canhoto', p_nova_previsao,
      'motivo_postergacao', v_motivo,
      'limite_postergacao_dias_aplicado', v_limite,
      'politica_operacional_versao_id', v_operacao.politica_operacional_versao_id,
      'dispensa_aprovacao_gestor', true
    ),
    'ambos',
    'nota_fiscal_entrega_postergacoes_canhoto',
    v_postergacao.id::text
  );

  INSERT INTO public.logs_auditoria (
    usuario_id,
    ator_tipo,
    origem,
    tipo_evento,
    entidade_tipo,
    entidade_id,
    dados_antes,
    dados_depois
  ) VALUES (
    v_usuario_id,
    'usuario',
    'rpc',
    'CANHOTO_POSTERGACAO_COMUNICADA',
    'nota_fiscal_entrega_postergacoes_canhoto',
    v_postergacao.id,
    jsonb_build_object(
      'prazo_original_upload_canhoto', v_prazo_original,
      'postergacao_utilizada', false
    ),
    jsonb_build_object(
      'nota_fiscal_id', v_nf.id,
      'nota_fiscal_entrega_id', v_entrega.id,
      'operacao_id', v_operacao.id,
      'fundo_id', v_nf.fundo_id,
      'cedente_id', v_nf.cedente_id,
      'cedente_fundo_id', v_nf.cedente_fundo_id,
      'prazo_original_upload_canhoto', v_prazo_original,
      'nova_previsao_upload_canhoto', p_nova_previsao,
      'motivo_postergacao', v_motivo,
      'limite_postergacao_dias_aplicado', v_limite,
      'politica_operacional_versao_id', v_operacao.politica_operacional_versao_id,
      'politica_snapshot_hash', v_operacao.politica_snapshot_hash,
      'postergacao_utilizada', true,
      'dispensa_aprovacao_gestor', true
    )
  );

  INSERT INTO public.notificacoes (
    usuario_id,
    titulo,
    mensagem,
    tipo,
    dedupe_key,
    entidade_tipo,
    entidade_id,
    href
  )
  SELECT DISTINCT
    uf.usuario_id,
    'Nova previsao de upload do canhoto',
    'O cedente ' || COALESCE(NULLIF(v_perfil.nome_completo, ''), NULLIF(v_perfil.email, ''), 'não identificado') ||
      ' comunicou nova previsão para upload do canhoto da NF ' || v_nf.numero_nf ||
      '. Prazo original: ' || to_char(v_prazo_original, 'DD/MM/YYYY') ||
      '. Nova previsão: ' || to_char(p_nova_previsao, 'DD/MM/YYYY') ||
      '. Motivo: ' || v_motivo ||
      '. Comunicada em: ' || to_char(CURRENT_TIMESTAMP, 'DD/MM/YYYY HH24:MI') || '.',
    'info',
    'nf:' || v_nf.id::text || ':canhoto_postergacao:' || uf.usuario_id::text,
    'notas_fiscais',
    v_nf.id,
    '/gestor/notas-fiscais/' || v_nf.id::text
  FROM public.usuario_fundos uf
  JOIN public.profiles p ON p.id = uf.usuario_id
  WHERE uf.fundo_id = v_nf.fundo_id
    AND uf.status = 'ativo'
    AND p.role = 'gestor'
    AND p.status = 'ativo'
  ON CONFLICT (usuario_id, dedupe_key) DO NOTHING;

  RETURN jsonb_build_object(
    'id', v_postergacao.id,
    'nota_fiscal_id', v_nf.id,
    'nota_fiscal_entrega_id', v_entrega.id,
    'prazo_original_upload_canhoto', v_prazo_original,
    'nova_previsao_upload_canhoto', p_nova_previsao,
    'motivo_postergacao', v_motivo,
    'limite_postergacao_dias_aplicado', v_limite,
    'postergacao_comunicada_em', v_postergacao.postergacao_comunicada_em,
    'postergacao_comunicada_por', v_usuario_id,
    'data_minima', v_data_minima,
    'data_maxima', v_data_maxima
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.confirmar_match_manual(p_matching_resultado_id uuid, p_nota_fiscal_id uuid, p_motivo text, p_correlation_id uuid DEFAULT gen_random_uuid())
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'auth', 'pg_temp'
AS $function$
DECLARE
  v_resultado public.matching_resultados%ROWTYPE;
  v_vinculo_id uuid;
  v_user_id uuid := auth.uid();
  v_chave record;
BEGIN
  SELECT * INTO v_resultado
  FROM public.matching_resultados
  WHERE id = p_matching_resultado_id;

  IF NOT FOUND OR NOT private.financeiro_gestor_tem_acesso_fundo(v_resultado.fundo_id) THEN
    RAISE EXCEPTION USING ERRCODE = '42501', MESSAGE = 'Resultado de matching indisponivel para o fundo ativo';
  END IF;
  IF v_resultado.status NOT IN ('AMBIGUO', 'NAO_CONCILIADO', 'CONFLITO') THEN
    RAISE EXCEPTION USING ERRCODE = '22023', MESSAGE = 'Somente excecoes de matching podem ser associadas manualmente';
  END IF;
  IF length(btrim(coalesce(p_motivo, ''))) < 5 THEN
    RAISE EXCEPTION USING ERRCODE = '22023', MESSAGE = 'Informe um motivo com pelo menos 5 caracteres';
  END IF;
  IF NOT private.financeiro_autorizacao_consumida('confirmar_match_manual') THEN
    RAISE EXCEPTION USING ERRCODE = '42501', MESSAGE = 'Confirmacao TOTP fresca obrigatoria';
  END IF;
  IF NOT EXISTS (
    SELECT 1 FROM public.notas_fiscais nf
    WHERE nf.id = p_nota_fiscal_id AND nf.fundo_id = v_resultado.fundo_id
  ) THEN
    RAISE EXCEPTION USING ERRCODE = '42501', MESSAGE = 'A nota fiscal nao pertence ao fundo do resultado';
  END IF;

  SELECT id INTO v_vinculo_id
  FROM public.titulo_nf_vinculos
  WHERE fundo_id = v_resultado.fundo_id
    AND provedor = v_resultado.provedor
    AND identidade_externa = v_resultado.identidade_externa
    AND status = 'ATIVO'
    AND origem = 'MANUAL'
    AND nota_fiscal_id = p_nota_fiscal_id;
  IF FOUND THEN RETURN v_vinculo_id; END IF;

  IF EXISTS (
    SELECT 1 FROM public.titulo_nf_vinculos
    WHERE fundo_id = v_resultado.fundo_id
      AND provedor = v_resultado.provedor
      AND identidade_externa = v_resultado.identidade_externa
      AND status = 'ATIVO' AND origem = 'MANUAL'
  ) THEN
    RAISE EXCEPTION USING ERRCODE = '23505', MESSAGE = 'Ja existe vinculo manual ativo para este titulo';
  END IF;

  UPDATE public.titulo_nf_vinculos
  SET status = 'REVOGADO', revogado_em = clock_timestamp(), revogado_por = v_user_id,
      motivo_revogacao = 'Substituido por associacao manual confirmada'
  WHERE fundo_id = v_resultado.fundo_id
    AND provedor = v_resultado.provedor
    AND identidade_externa = v_resultado.identidade_externa
    AND status = 'ATIVO' AND origem = 'AUTOMATICO';

  INSERT INTO public.titulo_nf_vinculos (
    fundo_id, provedor, identidade_externa, nota_fiscal_id, origem, metodo,
    evidencias, candidate_count, criado_por, confirmado_em, confirmado_por, correlation_id
  ) VALUES (
    v_resultado.fundo_id, v_resultado.provedor, v_resultado.identidade_externa,
    p_nota_fiscal_id, 'MANUAL', 'MANUAL',
    jsonb_build_object('matching_resultado_id', v_resultado.id, 'motivo', btrim(p_motivo)),
    1, v_user_id, clock_timestamp(), v_user_id, p_correlation_id
  ) RETURNING id INTO v_vinculo_id;

  FOR v_chave IN
    SELECT * FROM (VALUES
      ('ID_RECEBIVEL', v_resultado.id_recebivel),
      ('SEU_NUMERO', v_resultado.seu_numero),
      ('CHAVE_NFE', v_resultado.chave_nfe),
      ('EXTERNAL_TITLE_KEY', v_resultado.identidade_externa),
      ('DOCUMENTO', v_resultado.numero_documento)
    ) AS x(tipo, valor)
    WHERE valor IS NOT NULL AND length(btrim(valor)) > 0
  LOOP
    INSERT INTO public.titulo_nf_vinculo_chaves (
      vinculo_id, fundo_id, provedor, tipo_chave, valor_normalizado, fonte
    ) VALUES (
      v_vinculo_id, v_resultado.fundo_id, v_resultado.provedor,
      v_chave.tipo, btrim(v_chave.valor), 'MATCH_MANUAL'
    ) ON CONFLICT DO NOTHING;
  END LOOP;

  INSERT INTO public.logs_auditoria (
    usuario_id, tipo_evento, entidade_tipo, entidade_id, dados_antes, dados_depois,
    ator_tipo, origem, ator_identificador
  ) VALUES (
    v_user_id, 'MATCH_MANUAL_CONFIRMADO', 'titulo_nf_vinculos', v_vinculo_id,
    jsonb_build_object('matching_resultado_id', v_resultado.id, 'status', v_resultado.status),
    jsonb_build_object('fundo_id', v_resultado.fundo_id, 'nota_fiscal_id', p_nota_fiscal_id,
      'identidade_externa', v_resultado.identidade_externa, 'correlation_id', p_correlation_id),
    'usuario', 'gestor_conciliacao', v_user_id::text
  );
  RETURN v_vinculo_id;
END;
$function$

CREATE OR REPLACE FUNCTION public.corrigir_duplicata(p_duplicata_id uuid, p_campos jsonb, p_motivo text, p_resultado_confronto text)
 RETURNS duplicatas
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'private'
AS $function$
DECLARE
  v_user_id uuid := (SELECT auth.uid());
  v_role text := (SELECT public.get_user_role());
  v_old public.duplicatas%ROWTYPE;
  v_new public.duplicatas%ROWTYPE;
  v_version uuid;
  v_key text;
  v_old_value jsonb;
  v_new_value jsonb;
  v_actor_name text;
BEGIN
  IF v_user_id IS NULL THEN RAISE EXCEPTION 'Usuario nao autenticado'; END IF;
  IF length(btrim(coalesce(p_motivo, ''))) = 0 THEN RAISE EXCEPTION 'Informe o motivo da correcao'; END IF;
  SELECT * INTO v_old FROM public.duplicatas d WHERE d.id = p_duplicata_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Duplicata nao encontrada'; END IF;
  IF NOT (
    (v_role = 'cedente' AND v_old.cedente_id = (SELECT public.get_user_cedente_id()))
    OR (v_role = 'gestor' AND (SELECT private.usuario_tem_acesso_fundo(v_old.fundo_id)))
  ) THEN RAISE EXCEPTION 'Usuario sem permissao para corrigir a duplicata'; END IF;
  IF v_old.status_validacao IN ('VALIDADA', 'REJEITADA') THEN
    RAISE EXCEPTION 'Duplicata finalizada nao pode ser alterada';
  END IF;
  IF v_role = 'cedente' AND NOT EXISTS (
    SELECT 1 FROM public.notas_fiscais nf
    WHERE nf.id = v_old.nota_fiscal_id
      AND nf.status IN ('rascunho', 'requer_ajuste')
  ) THEN
    RAISE EXCEPTION 'A correcao pelo cedente deve ocorrer antes da submissao da NF';
  END IF;
  v_version := v_old.versao_atual_id;
  IF v_version IS NULL THEN RAISE EXCEPTION 'Duplicata sem versao documental atual'; END IF;

  FOREACH v_key IN ARRAY ARRAY['numero','numero_fatura','parcela','data_emissao','data_vencimento','valor_nominal','nome_cedente_documento','cnpj_cedente_documento','nome_sacado_documento','cnpj_sacado_documento','local_pagamento','aceite_textual'] LOOP
    IF p_campos ? v_key THEN
      v_old_value := to_jsonb(v_old)->v_key;
      v_new_value := p_campos->v_key;
      IF v_old_value IS DISTINCT FROM v_new_value THEN
        INSERT INTO public.duplicata_correcoes (
          duplicata_id, duplicata_versao_id, campo, valor_original, valor_corrigido,
          motivo, corrigido_por
        ) VALUES (v_old.id, v_version, v_key, v_old_value, v_new_value, btrim(p_motivo), v_user_id);
      END IF;
    END IF;
  END LOOP;

  UPDATE public.duplicatas SET
    numero = CASE WHEN p_campos ? 'numero' THEN nullif(btrim(p_campos->>'numero'), '') ELSE numero END,
    numero_fatura = CASE WHEN p_campos ? 'numero_fatura' THEN nullif(btrim(p_campos->>'numero_fatura'), '') ELSE numero_fatura END,
    parcela = CASE WHEN p_campos ? 'parcela' THEN coalesce(btrim(p_campos->>'parcela'), '') ELSE parcela END,
    data_emissao = CASE WHEN p_campos ? 'data_emissao' THEN nullif(p_campos->>'data_emissao', '')::date ELSE data_emissao END,
    data_vencimento = CASE WHEN p_campos ? 'data_vencimento' THEN nullif(p_campos->>'data_vencimento', '')::date ELSE data_vencimento END,
    valor_nominal = CASE WHEN p_campos ? 'valor_nominal' THEN nullif(p_campos->>'valor_nominal', '')::numeric ELSE valor_nominal END,
    nome_cedente_documento = CASE WHEN p_campos ? 'nome_cedente_documento' THEN nullif(btrim(p_campos->>'nome_cedente_documento'), '') ELSE nome_cedente_documento END,
    cnpj_cedente_documento = CASE WHEN p_campos ? 'cnpj_cedente_documento' THEN nullif(regexp_replace(p_campos->>'cnpj_cedente_documento', '[^0-9]', '', 'g'), '') ELSE cnpj_cedente_documento END,
    nome_sacado_documento = CASE WHEN p_campos ? 'nome_sacado_documento' THEN nullif(btrim(p_campos->>'nome_sacado_documento'), '') ELSE nome_sacado_documento END,
    cnpj_sacado_documento = CASE WHEN p_campos ? 'cnpj_sacado_documento' THEN nullif(regexp_replace(p_campos->>'cnpj_sacado_documento', '[^0-9]', '', 'g'), '') ELSE cnpj_sacado_documento END,
    local_pagamento = CASE WHEN p_campos ? 'local_pagamento' THEN nullif(btrim(p_campos->>'local_pagamento'), '') ELSE local_pagamento END,
    aceite_textual = CASE WHEN p_campos ? 'aceite_textual' THEN nullif(btrim(p_campos->>'aceite_textual'), '') ELSE aceite_textual END,
    aceite_detectado_textualmente = CASE
      WHEN NOT (p_campos ? 'aceite_textual') THEN aceite_detectado_textualmente
      WHEN nullif(btrim(p_campos->>'aceite_textual'), '') IS NULL THEN 'INDETERMINADO'
      WHEN lower(p_campos->>'aceite_textual') LIKE '%nao%'
        OR lower(p_campos->>'aceite_textual') LIKE '%não%'
        OR lower(p_campos->>'aceite_textual') LIKE '%sem %' THEN 'NAO'
      ELSE 'SIM'
    END,
    status_validacao = 'REVISAR',
    metodo_extracao = 'MANUAL',
    resultado_confronto = p_resultado_confronto,
    validado_por = NULL,
    validado_em = NULL,
    motivo_rejeicao = NULL
  WHERE id = v_old.id RETURNING * INTO v_new;

  SELECT coalesce(p.nome_completo, p.email, 'Usuario') INTO v_actor_name FROM public.profiles p WHERE p.id = v_user_id;
  INSERT INTO public.eventos_dominio (
    tenant_id, fundo_id, cedente_id, cedente_fundo_id, nota_fiscal_id,
    tipo_evento, categoria, ator_usuario_id, ator_nome_snapshot,
    ator_perfil_snapshot, origem, descricao, metadata, visibilidade,
    origem_evento, origem_registro_id
  ) VALUES (
    v_new.fundo_id, v_new.fundo_id, v_new.cedente_id, v_new.cedente_fundo_id, v_new.nota_fiscal_id,
    'duplicata_corrigida', 'analise', v_user_id, v_actor_name, v_role,
    'app', 'Campos da duplicata foram corrigidos manualmente.',
    jsonb_build_object('duplicata_id', v_new.id, 'campos', (SELECT jsonb_agg(key) FROM jsonb_each(p_campos))),
    'ambos', 'duplicatas', v_new.id::text || ':' || extract(epoch FROM clock_timestamp())::text
  );
  RETURN v_new;
END;
$function$

CREATE OR REPLACE FUNCTION public.criar_autorizacao_acao_sensivel(p_action_type text, p_nonce_hash text)
 RETURNS TABLE(expira_em timestamp with time zone)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE v_user_id uuid:=auth.uid(); v_session_id uuid; v_agora timestamptz:=clock_timestamp();
BEGIN
  BEGIN v_session_id:=nullif(auth.jwt()->>'session_id','')::uuid; EXCEPTION WHEN others THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='Sessao Supabase invalida'; END;
  IF p_action_type IS NULL OR p_action_type NOT IN ('alterar_senha','alterar_email','regenerar_recovery_codes','encerrar_outras_sessoes','reset_mfa_administrativo','cadastrar_credencial_integracao','rotacionar_credencial_integracao','ativar_credencial_integracao','revogar_credencial_integracao','criar_fundo','atualizar_fundo_estrutural','ativar_fundo','desativar_fundo','convidar_usuario_admin','vincular_gestor_fundo','revogar_gestor_fundo','reativar_gestor_fundo','desativar_usuario','reativar_usuario','conceder_super_admin','revogar_super_admin','criar_integracao_versao','publicar_integracao','desativar_integracao','testar_integracao','atualizar_cnab','atualizar_codigo_originador','publicar_base_financeira','confirmar_match_manual','revogar_match_manual','revisar_risco_operacao')
     OR p_nonce_hash!~'^[0-9a-f]{64}$' THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='Tipo de acao sensivel ou nonce invalido'; END IF;
  IF NOT EXISTS(SELECT 1 FROM public.obter_sessao_mfa_atual() estado WHERE estado.status='valid' AND estado.session_id=v_session_id) THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='Sessao MFA de 24 horas invalida'; END IF;
  INSERT INTO public.autorizacoes_acoes_sensiveis(user_id,session_id,action_type,nonce_hash,criada_em,expira_em) VALUES(v_user_id,v_session_id,p_action_type,p_nonce_hash,v_agora,v_agora+interval '5 minutes');
  RETURN QUERY SELECT v_agora+interval '5 minutes';
END; $function$

CREATE OR REPLACE FUNCTION public.decidir_revisao_risco(p_revisao_id uuid, p_decisao text, p_justificativa text, p_correlation_id uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE v_rev public.risco_revisoes%ROWTYPE; v_actor uuid:=auth.uid(); v_event text;
BEGIN
  IF v_actor IS NULL OR p_decisao NOT IN ('LIBERADA','RECUSADA') OR char_length(pg_catalog.btrim(p_justificativa)) NOT BETWEEN 5 AND 1000 THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='Decisao ou justificativa de revisao invalida'; END IF;
  SELECT * INTO v_rev FROM public.risco_revisoes WHERE id=p_revisao_id FOR UPDATE;
  IF NOT FOUND OR v_rev.status<>'PENDENTE' THEN RAISE EXCEPTION 'Revisao pendente nao encontrada'; END IF;
  IF NOT private.financeiro_gestor_tem_acesso_fundo(v_rev.fundo_id) THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='Gestor sem acesso ativo ao fundo'; END IF;
  IF NOT EXISTS(SELECT 1 FROM public.usuario_papeis up WHERE up.usuario_id=v_actor AND up.papel::text='gestor' AND up.ativo) AND public.get_user_role()::text<>'gestor' THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='Super Admin puro nao pode decidir risco operacional'; END IF;
  IF NOT private.financeiro_autorizacao_consumida('revisar_risco_operacao') THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='Confirmacao TOTP fresca obrigatoria'; END IF;
  IF EXISTS(SELECT 1 FROM public.risco_execucoes newer WHERE newer.operacao_id=v_rev.operacao_id AND newer.created_at>(SELECT created_at FROM public.risco_execucoes WHERE id=v_rev.risco_execucao_id)) THEN
    UPDATE public.risco_revisoes SET status='EXPIRADA',justificativa='Avaliacao substituida por uma execucao mais recente',revisado_por=v_actor,revisado_em=clock_timestamp(),updated_at=clock_timestamp() WHERE id=v_rev.id;
    INSERT INTO public.logs_auditoria(usuario_id,tipo_evento,entidade_tipo,entidade_id,dados_depois) VALUES(v_actor,'RISCO_REVISAO_EXPIRADA','operacoes',v_rev.operacao_id,pg_catalog.jsonb_build_object('fundo_id',v_rev.fundo_id,'risco_revisao_id',v_rev.id,'correlation_id',p_correlation_id));
    RETURN false;
  END IF;
  UPDATE public.risco_revisoes SET status=p_decisao,justificativa=pg_catalog.btrim(p_justificativa),revisado_por=v_actor,revisado_em=clock_timestamp(),updated_at=clock_timestamp() WHERE id=v_rev.id;
  v_event:=CASE p_decisao WHEN 'LIBERADA' THEN 'RISCO_REVISAO_LIBERADA' ELSE 'RISCO_REVISAO_RECUSADA' END;
  INSERT INTO public.logs_auditoria(usuario_id,tipo_evento,entidade_tipo,entidade_id,dados_depois) VALUES(v_actor,v_event,'operacoes',v_rev.operacao_id,pg_catalog.jsonb_build_object('fundo_id',v_rev.fundo_id,'risco_revisao_id',v_rev.id,'correlation_id',p_correlation_id));
  RETURN true;
END; $function$

CREATE OR REPLACE FUNCTION public.desembolsar_operacao_com_logistica(p_operacao_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  op record;
  escrow_saldo numeric;
  novo_saldo numeric;
  now_ts timestamptz := now();
  cria_entrega boolean;
  cte_prazo integer;
  comprovante_prazo integer;
  nf record;
  entrega_id uuid;
  inserted_deliveries integer := 0;
  inserted_requirements integer := 0;
  req record;
  req_prazo_limite date;
BEGIN
  IF auth.uid() IS NULL OR get_user_role() <> 'gestor' THEN
    RAISE EXCEPTION 'Somente gestor pode desembolsar operacao';
  END IF;

  SELECT * INTO op FROM public.operacoes WHERE id = p_operacao_id FOR UPDATE;
  IF op.id IS NULL THEN RAISE EXCEPTION 'Operacao nao encontrada'; END IF;
  IF op.status <> 'aprovada' THEN RAISE EXCEPTION 'Operacao nao esta aprovada para desembolso'; END IF;
  IF op.termo_assinado_url IS NULL THEN RAISE EXCEPTION 'Termo de cessao assinado ausente'; END IF;
  IF op.comprovante_pagamento_url IS NULL THEN RAISE EXCEPTION 'Comprovante de desembolso ausente'; END IF;
  IF op.politica_snapshot IS NULL OR op.politica_operacional_versao_id IS NULL THEN
    RAISE EXCEPTION 'Operacao sem snapshot de politica operacional';
  END IF;

  SELECT saldo_disponivel INTO escrow_saldo FROM public.contas_escrow WHERE id = op.conta_escrow_id FOR UPDATE;
  IF escrow_saldo IS NULL THEN RAISE EXCEPTION 'Conta escrow nao encontrada'; END IF;
  novo_saldo := escrow_saldo + op.valor_liquido_desembolso;

  cria_entrega := COALESCE((op.politica_snapshot->>'cria_acompanhamento_entrega')::boolean, false);

  SELECT min(NULLIF(item->>'prazo_dias_corridos', '')::integer)
    INTO cte_prazo
  FROM jsonb_array_elements(COALESCE(op.politica_snapshot->'requisitos', '[]'::jsonb)) item
  WHERE COALESCE((item->>'ativo')::boolean, false)
    AND item->>'escopo' IN ('pos_cessao', 'entrega')
    AND COALESCE(item->>'tipo_documento_codigo', item->>'codigo') = 'cte'
    AND NULLIF(item->>'prazo_dias_corridos', '') IS NOT NULL;

  SELECT min(NULLIF(item->>'prazo_dias_corridos', '')::integer)
    INTO comprovante_prazo
  FROM jsonb_array_elements(COALESCE(op.politica_snapshot->'requisitos', '[]'::jsonb)) item
  WHERE COALESCE((item->>'ativo')::boolean, false)
    AND item->>'escopo' IN ('pos_cessao', 'entrega')
    AND COALESCE(item->>'tipo_documento_codigo', item->>'codigo') IN ('canhoto', 'comprovante_entrega')
    AND NULLIF(item->>'prazo_dias_corridos', '') IS NOT NULL;

  UPDATE public.operacoes
  SET status = 'em_andamento',
      cessao_efetivada_em = COALESCE(cessao_efetivada_em, now_ts)
  WHERE id = p_operacao_id;

  UPDATE public.contas_escrow SET saldo_disponivel = novo_saldo WHERE id = op.conta_escrow_id;

  INSERT INTO public.movimentos_escrow (
    conta_escrow_id, tipo, descricao, valor, saldo_apos, operacao_id
  )
  VALUES (
    op.conta_escrow_id, 'credito',
    'Desembolso antecipacao - Operacao ' || substring(p_operacao_id::text from 1 for 8),
    op.valor_liquido_desembolso, novo_saldo, p_operacao_id
  );

  FOR nf IN
    SELECT n.id, n.cedente_id
    FROM public.operacoes_nfs onf
    JOIN public.notas_fiscais n ON n.id = onf.nota_fiscal_id
    WHERE onf.operacao_id = p_operacao_id
    ORDER BY n.id
  LOOP
    INSERT INTO public.nota_fiscal_entregas (
      operacao_id, nota_fiscal_id, status_entrega, cessao_efetivada_em,
      data_limite_cte, data_limite_canhoto
    )
    VALUES (
      p_operacao_id, nf.id,
      CASE WHEN cria_entrega THEN 'em_transito' ELSE 'nao_aplicavel' END,
      now_ts,
      CASE WHEN cria_entrega AND cte_prazo IS NOT NULL THEN (now_ts::date + cte_prazo) ELSE NULL END,
      CASE WHEN cria_entrega AND comprovante_prazo IS NOT NULL THEN (now_ts::date + comprovante_prazo) ELSE NULL END
    )
    ON CONFLICT (operacao_id, nota_fiscal_id) DO UPDATE
      SET status_entrega = public.nota_fiscal_entregas.status_entrega
    RETURNING id INTO entrega_id;

    inserted_deliveries := inserted_deliveries + 1;
    PERFORM public.registrar_evento_entrega(
      entrega_id,
      'cessao_efetivada',
      NULL,
      CASE WHEN cria_entrega THEN 'em_transito' ELSE 'nao_aplicavel' END,
      'sistema',
      jsonb_build_object('operacao_id', p_operacao_id)
    );

    IF cria_entrega THEN
      FOR req IN
        SELECT
          COALESCE(NULLIF(item->>'id', '')::uuid, pr.id) AS politica_requisito_id,
          pr.politica_operacional_id,
          pr.politica_operacional_versao_id,
          COALESCE(NULLIF(item->>'documento_tipo_id', '')::uuid, pr.documento_tipo_id, dt.id) AS documento_tipo_id,
          item->>'codigo' AS codigo,
          COALESCE(item->>'tipo_documento_codigo', item->>'codigo') AS tipo_documento_codigo,
          item->>'escopo' AS escopo,
          COALESCE((item->>'obrigatorio')::boolean, pr.obrigatorio) AS obrigatorio,
          NULLIF(item->>'prazo_dias_corridos', '')::integer AS prazo_dias_corridos,
          COALESCE(
            CASE
              WHEN jsonb_typeof(item->'formatos_aceitos') = 'array'
                THEN ARRAY(SELECT jsonb_array_elements_text(item->'formatos_aceitos'))
              ELSE NULL
            END,
            pr.formatos_aceitos
          ) AS formatos_aceitos,
          COALESCE(NULLIF(item->>'nivel_validacao', ''), pr.nivel_validacao) AS nivel_validacao,
          COALESCE(NULLIF(item->>'quantidade_minima', '')::integer, pr.quantidade_minima) AS quantidade_minima,
          COALESCE(NULLIF(item->>'responsavel_upload', ''), pr.responsavel_upload) AS responsavel_upload,
          COALESCE(NULLIF(item->>'responsavel_aprovacao', ''), pr.responsavel_aprovacao) AS responsavel_aprovacao
        FROM jsonb_array_elements(COALESCE(op.politica_snapshot->'requisitos', '[]'::jsonb)) item
        JOIN public.politica_requisitos_documentais pr
          ON pr.politica_operacional_versao_id = op.politica_operacional_versao_id
         AND (
           pr.id = NULLIF(item->>'id', '')::uuid
           OR pr.codigo = item->>'codigo'
           OR pr.tipo_documento_codigo = COALESCE(item->>'tipo_documento_codigo', item->>'codigo')
         )
        LEFT JOIN public.documento_tipos dt
          ON dt.codigo = COALESCE(item->>'tipo_documento_codigo', item->>'codigo')
         AND dt.ativo = true
        WHERE COALESCE((item->>'ativo')::boolean, false)
          AND item->>'escopo' IN ('pos_cessao', 'entrega')
      LOOP
        req_prazo_limite := CASE
          WHEN req.prazo_dias_corridos IS NOT NULL THEN now_ts::date + req.prazo_dias_corridos
          ELSE NULL
        END;

        INSERT INTO public.documento_requisito_instancias (
          politica_requisito_id, politica_operacional_id, politica_operacional_versao_id, politica_versao,
          documento_tipo_id, tipo_documento_codigo_snapshot, escopo_snapshot, nota_fiscal_entrega_id,
          cedente_id, status, obrigatorio, prazo_limite, formatos_aceitos_snapshot,
          nivel_validacao_snapshot, quantidade_minima_snapshot, responsavel_upload_snapshot,
          responsavel_aprovacao_snapshot
        )
        VALUES (
          req.politica_requisito_id, req.politica_operacional_id, req.politica_operacional_versao_id, op.politica_versao,
          req.documento_tipo_id, req.tipo_documento_codigo, req.escopo, entrega_id,
          op.cedente_id, 'pendente', req.obrigatorio, req_prazo_limite,
          req.formatos_aceitos, req.nivel_validacao, req.quantidade_minima,
          req.responsavel_upload, req.responsavel_aprovacao
        )
        ON CONFLICT (politica_requisito_id, nota_fiscal_entrega_id) DO UPDATE
          SET documento_tipo_id = COALESCE(documento_requisito_instancias.documento_tipo_id, EXCLUDED.documento_tipo_id),
              prazo_limite = COALESCE(documento_requisito_instancias.prazo_limite, EXCLUDED.prazo_limite);

        inserted_requirements := inserted_requirements + 1;

        PERFORM public.registrar_evento_entrega(
          entrega_id,
          CASE WHEN req.tipo_documento_codigo = 'cte' THEN 'cte_pendente' ELSE 'canhoto_pendente' END,
          'em_transito',
          'em_transito',
          'sistema',
          jsonb_build_object(
            'tipo_documento_codigo', req.tipo_documento_codigo,
            'prazo_limite', req_prazo_limite,
            'codigo_requisito', req.codigo,
            'fonte', 'politica_snapshot'
          )
        );
      END LOOP;
    END IF;
  END LOOP;

  INSERT INTO public.notificacoes (usuario_id, titulo, mensagem, tipo, dedupe_key)
  SELECT c.user_id, 'Cessao efetivada',
         'A operacao ' || substring(p_operacao_id::text from 1 for 8) || ' foi desembolsada e a cessao foi efetivada.',
         'cessao_efetivada',
         'operacao:' || p_operacao_id::text || ':cessao_efetivada:' || c.user_id::text
  FROM public.cedentes c WHERE c.id = op.cedente_id
  ON CONFLICT (usuario_id, dedupe_key) DO NOTHING;

  RETURN jsonb_build_object(
    'operacao_id', p_operacao_id,
    'saldo_apos', novo_saldo,
    'entregas', inserted_deliveries,
    'requisitos_pos_cessao', inserted_requirements,
    'cria_acompanhamento_entrega', cria_entrega,
    'fonte_requisitos', 'politica_snapshot'
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.persistir_conciliacao_execucao(p_payload jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'pg_catalog', 'pg_temp'
AS $function$
DECLARE
  v_fundo_id uuid := (p_payload ->> 'fundo_id')::uuid;
  v_execucao_id uuid;
  v_item jsonb;
  v_status text := p_payload ->> 'status';
  v_inputs uuid[] := ARRAY(SELECT jsonb_array_elements_text(coalesce(p_payload -> 'input_import_ids', '[]'::jsonb))::uuid);
BEGIN
  IF NOT private.financeiro_chamada_service_role() THEN
    RAISE EXCEPTION USING ERRCODE = '42501', MESSAGE = 'Persistencia de conciliacao restrita ao processador interno';
  END IF;
  PERFORM pg_advisory_xact_lock(hashtextextended(
    'financeiro-conciliacao:' || v_fundo_id::text || ':' || (p_payload ->> 'data_referencia'), 0
  ));
  SELECT id INTO v_execucao_id FROM public.conciliacao_execucoes
  WHERE fundo_id = v_fundo_id AND assinatura_execucao = p_payload ->> 'assinatura_execucao';
  IF FOUND THEN RETURN v_execucao_id; END IF;

  IF v_status <> 'BASE_INCOMPLETA' AND (
    SELECT count(*) FROM public.importacoes_financeiras i
    WHERE i.id = ANY(v_inputs) AND i.fundo_id = v_fundo_id AND i.status = 'PUBLICADA'
      AND i.completude IN ('COMPLETO_COM_DADOS', 'COMPLETO_VAZIO')
  ) <> 4 THEN
    RAISE EXCEPTION USING ERRCODE = '22023', MESSAGE = 'Inputs publicados/completos da conciliacao sao invalidos';
  END IF;

  INSERT INTO public.conciliacao_execucoes (
    fundo_id, data_referencia, regra_versao, estoque_d2_importacao_id,
    estoque_d1_importacao_id, aquisicoes_d1_importacao_id, liquidacoes_d1_importacao_id,
    matching_execucao_id, assinatura_execucao, correlation_id, criado_por, detalhes
  ) VALUES (
    v_fundo_id, (p_payload ->> 'data_referencia')::date, p_payload ->> 'regra_versao',
    nullif(p_payload ->> 'estoque_d2_importacao_id', '')::uuid,
    nullif(p_payload ->> 'estoque_d1_importacao_id', '')::uuid,
    nullif(p_payload ->> 'aquisicoes_d1_importacao_id', '')::uuid,
    nullif(p_payload ->> 'liquidacoes_d1_importacao_id', '')::uuid,
    nullif(p_payload ->> 'matching_execucao_id', '')::uuid,
    p_payload ->> 'assinatura_execucao', (p_payload ->> 'correlation_id')::uuid,
    nullif(p_payload ->> 'criado_por', '')::uuid, coalesce(p_payload -> 'detalhes', '{}'::jsonb)
  ) RETURNING id INTO v_execucao_id;

  IF v_status <> 'BASE_INCOMPLETA' THEN
    FOR v_item IN SELECT value FROM jsonb_array_elements(coalesce(p_payload -> 'resultados', '[]'::jsonb))
    LOOP
      INSERT INTO public.conciliacao_resultados (
        execucao_id, fundo_id, identidade_externa, provedor, vinculo_id, nota_fiscal_id,
        presente_d2, presente_d1, valor_aquisicao_d2, valor_aquisicao_d1,
        aquisicoes_count, aquisicoes_valor, liquidacoes_count, liquidacoes_valor_pago,
        status, detalhes
      ) VALUES (
        v_execucao_id, v_fundo_id, v_item ->> 'identidade_externa', v_item ->> 'provedor',
        nullif(v_item ->> 'vinculo_id', '')::uuid, nullif(v_item ->> 'nota_fiscal_id', '')::uuid,
        coalesce((v_item ->> 'presente_d2')::boolean, false),
        coalesce((v_item ->> 'presente_d1')::boolean, false),
        nullif(v_item ->> 'valor_aquisicao_d2', '')::numeric,
        nullif(v_item ->> 'valor_aquisicao_d1', '')::numeric,
        coalesce((v_item ->> 'aquisicoes_count')::integer, 0),
        coalesce((v_item ->> 'aquisicoes_valor')::numeric, 0),
        coalesce((v_item ->> 'liquidacoes_count')::integer, 0),
        coalesce((v_item ->> 'liquidacoes_valor_pago')::numeric, 0),
        v_item ->> 'status', coalesce(v_item -> 'detalhes', '{}'::jsonb)
      );
    END LOOP;
  END IF;

  UPDATE public.conciliacao_execucoes SET
    status = v_status, contagens = coalesce(p_payload -> 'contagens', '{}'::jsonb),
    valores_agregados = coalesce(p_payload -> 'valores_agregados', '{}'::jsonb),
    finalizado_em = clock_timestamp()
  WHERE id = v_execucao_id;

  INSERT INTO public.logs_auditoria (
    usuario_id, tipo_evento, entidade_tipo, entidade_id, dados_depois,
    ator_tipo, origem, ator_identificador
  ) VALUES (
    nullif(p_payload ->> 'criado_por', '')::uuid,
    CASE WHEN v_status = 'BASE_INCOMPLETA' THEN 'CONCILIACAO_BASE_INCOMPLETA' ELSE 'CONCILIACAO_EXECUTADA' END,
    'conciliacao_execucoes', v_execucao_id,
    jsonb_build_object('fundo_id', v_fundo_id, 'data_referencia', p_payload ->> 'data_referencia',
      'status', v_status, 'contagens', p_payload -> 'contagens',
      'correlation_id', p_payload ->> 'correlation_id'),
    'usuario', 'gestor_conciliacao', p_payload ->> 'criado_por'
  );
  RETURN v_execucao_id;
END;
$function$

CREATE OR REPLACE FUNCTION public.persistir_matching_execucao(p_payload jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'pg_catalog', 'pg_temp'
AS $function$
DECLARE
  v_fundo_id uuid := (p_payload ->> 'fundo_id')::uuid;
  v_execucao_id uuid;
  v_resultado_id uuid;
  v_vinculo_id uuid;
  v_existente public.titulo_nf_vinculos%ROWTYPE;
  v_item jsonb;
  v_candidate jsonb;
  v_chave jsonb;
  v_status text;
  v_metodo text;
  v_total integer := 0;
  v_matched integer := 0;
  v_ambiguos integer := 0;
  v_nao_conciliados integer := 0;
  v_conflitos integer := 0;
  v_valor_total numeric(24,2) := 0;
  v_valor_matched numeric(24,2) := 0;
  v_valor_ambiguo numeric(24,2) := 0;
  v_valor_nao_conciliado numeric(24,2) := 0;
BEGIN
  IF NOT private.financeiro_chamada_service_role() THEN
    RAISE EXCEPTION USING ERRCODE = '42501', MESSAGE = 'Persistencia de matching restrita ao processador interno';
  END IF;
  IF v_fundo_id IS NULL OR jsonb_array_length(coalesce(p_payload -> 'resultados', '[]'::jsonb)) = 0 THEN
    RAISE EXCEPTION USING ERRCODE = '22023', MESSAGE = 'Payload de matching invalido';
  END IF;

  PERFORM pg_advisory_xact_lock(hashtextextended(
    'financeiro-matching:' || v_fundo_id::text || ':' || (p_payload ->> 'data_referencia'), 0
  ));

  SELECT id INTO v_execucao_id
  FROM public.matching_execucoes
  WHERE fundo_id = v_fundo_id AND assinatura_execucao = p_payload ->> 'assinatura_execucao';
  IF FOUND THEN RETURN v_execucao_id; END IF;

  IF (
    SELECT count(*)
    FROM public.importacoes_financeiras i
    WHERE i.id = ANY(ARRAY(SELECT jsonb_array_elements_text(p_payload -> 'input_import_ids')::uuid))
      AND i.fundo_id = v_fundo_id AND i.status = 'PUBLICADA'
  ) <> jsonb_array_length(p_payload -> 'input_import_ids') THEN
    RAISE EXCEPTION USING ERRCODE = '22023', MESSAGE = 'Inputs de matching nao estao publicados no fundo informado';
  END IF;

  INSERT INTO public.matching_execucoes (
    fundo_id, data_referencia, regra_versao, input_import_ids, assinatura_execucao,
    correlation_id, criado_por, detalhes
  ) VALUES (
    v_fundo_id, (p_payload ->> 'data_referencia')::date, p_payload ->> 'regra_versao',
    ARRAY(SELECT jsonb_array_elements_text(p_payload -> 'input_import_ids')::uuid),
    p_payload ->> 'assinatura_execucao', (p_payload ->> 'correlation_id')::uuid,
    nullif(p_payload ->> 'criado_por', '')::uuid,
    jsonb_build_object('processamento', 'RPC_TRANSACIONAL', 'imutavel', true)
  ) RETURNING id INTO v_execucao_id;

  FOR v_item IN SELECT value FROM jsonb_array_elements(p_payload -> 'resultados')
  LOOP
    v_total := v_total + 1;
    v_status := v_item ->> 'status';
    v_metodo := v_item ->> 'metodo';
    v_vinculo_id := NULL;
    v_valor_total := v_valor_total + coalesce(nullif(v_item ->> 'valor_referencia', '')::numeric, 0);

    IF v_status = 'MATCH_FORTE' THEN
      IF NOT EXISTS (
        SELECT 1 FROM public.notas_fiscais nf
        WHERE nf.id = (v_item ->> 'nota_fiscal_id')::uuid AND nf.fundo_id = v_fundo_id
      ) THEN
        RAISE EXCEPTION USING ERRCODE = '42501', MESSAGE = 'NF candidata fora do fundo da execucao';
      END IF;

      SELECT * INTO v_existente
      FROM public.titulo_nf_vinculos
      WHERE fundo_id = v_fundo_id AND provedor = v_item ->> 'provedor'
        AND identidade_externa = v_item ->> 'identidade_externa' AND status = 'ATIVO';

      IF FOUND AND v_existente.nota_fiscal_id <> (v_item ->> 'nota_fiscal_id')::uuid THEN
        v_status := 'CONFLITO';
        v_metodo := 'CONFLITO';
      ELSIF FOUND THEN
        v_vinculo_id := v_existente.id;
      ELSE
        INSERT INTO public.titulo_nf_vinculos (
          fundo_id, provedor, identidade_externa, nota_fiscal_id, origem, metodo,
          regra_versao, evidencias, candidate_count, criado_por, correlation_id
        ) VALUES (
          v_fundo_id, v_item ->> 'provedor', v_item ->> 'identidade_externa',
          (v_item ->> 'nota_fiscal_id')::uuid, 'AUTOMATICO', v_metodo,
          p_payload ->> 'regra_versao', coalesce(v_item -> 'evidencias', '{}'::jsonb), 1,
          nullif(p_payload ->> 'criado_por', '')::uuid, (p_payload ->> 'correlation_id')::uuid
        ) RETURNING id INTO v_vinculo_id;

        FOR v_chave IN SELECT value FROM jsonb_array_elements(coalesce(v_item -> 'chaves', '[]'::jsonb))
        LOOP
          INSERT INTO public.titulo_nf_vinculo_chaves (
            vinculo_id, fundo_id, provedor, tipo_chave, valor_normalizado, fonte
          ) VALUES (
            v_vinculo_id, v_fundo_id, v_item ->> 'provedor', v_chave ->> 'tipo',
            v_chave ->> 'valor', 'MATCH_AUTOMATICO'
          ) ON CONFLICT DO NOTHING;
        END LOOP;
      END IF;
    END IF;

    IF v_status = 'MATCH_FORTE' THEN
      v_matched := v_matched + 1;
      v_valor_matched := v_valor_matched + coalesce(nullif(v_item ->> 'valor_referencia', '')::numeric, 0);
    ELSIF v_status = 'AMBIGUO' THEN
      v_ambiguos := v_ambiguos + 1;
      v_valor_ambiguo := v_valor_ambiguo + coalesce(nullif(v_item ->> 'valor_referencia', '')::numeric, 0);
    ELSIF v_status = 'CONFLITO' THEN
      v_conflitos := v_conflitos + 1;
    ELSE
      v_nao_conciliados := v_nao_conciliados + 1;
      v_valor_nao_conciliado := v_valor_nao_conciliado + coalesce(nullif(v_item ->> 'valor_referencia', '')::numeric, 0);
    END IF;

    INSERT INTO public.matching_resultados (
      execucao_id, fundo_id, provedor, origem_registro, origem_registro_id,
      identidade_externa, id_recebivel, seu_numero, chave_nfe, numero_documento,
      cedente_documento, cedente_nome, sacado_documento, sacado_nome,
      data_vencimento, valor_referencia, tipo_recebivel, status, metodo,
      nota_fiscal_id, vinculo_id, candidate_count, evidencias
    ) VALUES (
      v_execucao_id, v_fundo_id, v_item ->> 'provedor', v_item ->> 'origem_registro',
      (v_item ->> 'origem_registro_id')::uuid, v_item ->> 'identidade_externa',
      nullif(v_item ->> 'id_recebivel', ''), nullif(v_item ->> 'seu_numero', ''),
      nullif(v_item ->> 'chave_nfe', ''), nullif(v_item ->> 'numero_documento', ''),
      nullif(v_item ->> 'cedente_documento', ''), nullif(v_item ->> 'cedente_nome', ''),
      nullif(v_item ->> 'sacado_documento', ''), nullif(v_item ->> 'sacado_nome', ''),
      nullif(v_item ->> 'data_vencimento', '')::date,
      nullif(v_item ->> 'valor_referencia', '')::numeric, nullif(v_item ->> 'tipo_recebivel', ''),
      v_status, v_metodo,
      CASE WHEN v_status = 'MATCH_FORTE' THEN (v_item ->> 'nota_fiscal_id')::uuid ELSE NULL END,
      v_vinculo_id,
      CASE WHEN v_status = 'MATCH_FORTE' THEN 1 ELSE jsonb_array_length(coalesce(v_item -> 'candidatos', '[]'::jsonb)) END,
      coalesce(v_item -> 'evidencias', '{}'::jsonb) ||
        CASE WHEN v_status = 'CONFLITO' THEN jsonb_build_object('vinculo_ativo_conflitante', v_existente.id) ELSE '{}'::jsonb END
    ) RETURNING id INTO v_resultado_id;

    FOR v_candidate IN SELECT value FROM jsonb_array_elements(coalesce(v_item -> 'candidatos', '[]'::jsonb))
    LOOP
      IF EXISTS (
        SELECT 1 FROM public.notas_fiscais nf
        WHERE nf.id = (v_candidate ->> 'nota_fiscal_id')::uuid AND nf.fundo_id = v_fundo_id
      ) THEN
        INSERT INTO public.matching_candidatos (
          matching_resultado_id, fundo_id, nota_fiscal_id, ordem, metodo, evidencias
        ) VALUES (
          v_resultado_id, v_fundo_id, (v_candidate ->> 'nota_fiscal_id')::uuid,
          coalesce((v_candidate ->> 'ordem')::integer, 1), v_candidate ->> 'metodo',
          coalesce(v_candidate -> 'evidencias', '{}'::jsonb)
        ) ON CONFLICT DO NOTHING;
      END IF;
    END LOOP;
  END LOOP;

  UPDATE public.matching_execucoes SET
    status = 'CONCLUIDA', total_registros = v_total, matched = v_matched,
    ambiguos = v_ambiguos, nao_conciliados = v_nao_conciliados, conflitos = v_conflitos,
    valor_total = v_valor_total, valor_matched = v_valor_matched,
    valor_ambiguo = v_valor_ambiguo, valor_nao_conciliado = v_valor_nao_conciliado,
    finalizado_em = clock_timestamp()
  WHERE id = v_execucao_id;

  INSERT INTO public.logs_auditoria (
    usuario_id, tipo_evento, entidade_tipo, entidade_id, dados_depois,
    ator_tipo, origem, ator_identificador
  ) VALUES (
    nullif(p_payload ->> 'criado_por', '')::uuid, 'MATCHING_EXECUTADO',
    'matching_execucoes', v_execucao_id,
    jsonb_build_object('fundo_id', v_fundo_id, 'data_referencia', p_payload ->> 'data_referencia',
      'total', v_total, 'matched', v_matched, 'ambiguos', v_ambiguos,
      'nao_conciliados', v_nao_conciliados, 'conflitos', v_conflitos,
      'correlation_id', p_payload ->> 'correlation_id'),
    'usuario', 'gestor_conciliacao', p_payload ->> 'criado_por'
  );
  RETURN v_execucao_id;
END;
$function$

CREATE OR REPLACE FUNCTION public.processar_aceite_sacado(p_nota_fiscal_ids uuid[], p_acao text, p_motivo text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_user_id uuid := auth.uid();
  v_sacado_cnpj text;
  v_sacado_nome text;
  v_requested_count integer;
  v_found_count integer;
  v_nf record;
  v_op record;
  v_total integer;
  v_aceitas integer;
  v_operation_ids uuid[] := ARRAY[]::uuid[];
  v_nf_ids uuid[] := ARRAY[]::uuid[];
  v_event text;
  v_title text;
  v_message text;
  v_dedupe text;
  v_recipient uuid;
BEGIN
  IF v_user_id IS NULL OR get_user_role() <> 'sacado' THEN
    RAISE EXCEPTION 'Apenas um sacado autenticado pode executar esta operação.';
  END IF;

  IF p_acao NOT IN ('aceitar', 'contestar') THEN
    RAISE EXCEPTION 'Ação de aceite inválida.';
  END IF;

  IF p_nota_fiscal_ids IS NULL OR cardinality(p_nota_fiscal_ids) = 0 THEN
    RAISE EXCEPTION 'Nenhuma NF foi informada.';
  END IF;

  IF p_acao = 'contestar' AND COALESCE(trim(p_motivo), '') = '' THEN
    RAISE EXCEPTION 'O motivo da contestação é obrigatório.';
  END IF;

  SELECT s.cnpj, s.razao_social
    INTO v_sacado_cnpj, v_sacado_nome
    FROM public.sacados s
   WHERE s.user_id = v_user_id;
  IF v_sacado_cnpj IS NULL THEN
    RAISE EXCEPTION 'Sacado não encontrado.';
  END IF;

  v_requested_count := (SELECT count(DISTINCT nf_id) FROM unnest(p_nota_fiscal_ids) AS item(nf_id));
  SELECT count(DISTINCT nf.id)
    INTO v_found_count
    FROM public.notas_fiscais nf
    JOIN public.operacoes_nfs onf ON onf.nota_fiscal_id = nf.id
    JOIN public.operacoes op ON op.id = onf.operacao_id
   WHERE nf.id = ANY(p_nota_fiscal_ids);
  IF v_requested_count <> v_found_count THEN
    RAISE EXCEPTION 'Todas as NFs precisam estar vinculadas a uma operação.';
  END IF;

  IF EXISTS (
    SELECT 1
      FROM public.operacoes_nfs onf
     WHERE onf.nota_fiscal_id = ANY(p_nota_fiscal_ids)
     GROUP BY onf.nota_fiscal_id
    HAVING count(DISTINCT onf.operacao_id) <> 1
  ) THEN
    RAISE EXCEPTION 'A NF possui vínculo operacional ambíguo.';
  END IF;

  -- Locks determinísticos evitam corrida no último aceite de uma operação.
  PERFORM 1 FROM public.notas_fiscais WHERE id = ANY(p_nota_fiscal_ids) FOR UPDATE;
  FOR v_op IN
    SELECT op.id, op.cedente_id
      FROM public.operacoes op
     WHERE op.id IN (
       SELECT onf.operacao_id FROM public.operacoes_nfs onf WHERE onf.nota_fiscal_id = ANY(p_nota_fiscal_ids)
     )
     ORDER BY op.id
     FOR UPDATE
  LOOP
    v_operation_ids := array_append(v_operation_ids, v_op.id);
  END LOOP;

  FOR v_nf IN
    SELECT nf.id, nf.numero_nf, nf.cnpj_destinatario, nf.razao_social_emitente,
           nf.cedente_id, nf.status, onf.operacao_id,
           op.aceite_sacado_exigido, op.aceite_sacado_status, op.status AS operacao_status,
           c.razao_social AS cedente_razao_social
      FROM public.notas_fiscais nf
      JOIN public.operacoes_nfs onf ON onf.nota_fiscal_id = nf.id
      JOIN public.operacoes op ON op.id = onf.operacao_id
      JOIN public.cedentes c ON c.id = op.cedente_id
     WHERE nf.id = ANY(p_nota_fiscal_ids)
     ORDER BY nf.id
  LOOP
    IF v_nf.cnpj_destinatario <> v_sacado_cnpj THEN
      RAISE EXCEPTION 'Esta NF não é destinada ao sacado autenticado.';
    END IF;
    IF COALESCE(v_nf.aceite_sacado_exigido, true) = false
       OR COALESCE(v_nf.aceite_sacado_status, 'pendente') = 'dispensado' THEN
      RAISE EXCEPTION 'Esta operação não exige aceite do sacado.';
    END IF;
    IF v_nf.aceite_sacado_status IS NOT NULL AND v_nf.aceite_sacado_status <> 'pendente' THEN
      RAISE EXCEPTION 'A operação não está aberta para aceite.';
    END IF;
    IF v_nf.operacao_status NOT IN ('solicitada', 'em_analise') THEN
      RAISE EXCEPTION 'A operação não está aberta para aceite.';
    END IF;
    IF v_nf.status <> 'em_antecipacao' THEN
      RAISE EXCEPTION 'Esta NF não pode ser alterada no status atual.';
    END IF;

    IF p_acao = 'aceitar' THEN
      UPDATE public.notas_fiscais
         SET status = 'aceita', aprovacao_sacado_em = now()
       WHERE id = v_nf.id;
      v_event := 'CESSAO_ACEITA';
      v_title := 'Cessão aceita pelo sacado';
      v_message := format('O sacado %s aceitou a cessão da NF %s.', v_sacado_nome, v_nf.numero_nf);
    ELSE
      UPDATE public.notas_fiscais
         SET status = 'contestada', motivo_ajuste = p_motivo
       WHERE id = v_nf.id;
      v_event := 'CESSAO_CONTESTADA';
      v_title := 'ALERTA: Cessão contestada pelo sacado';
      v_message := format('O sacado %s contestou a cessão da NF %s. Motivo: %s', v_sacado_nome, v_nf.numero_nf, p_motivo);
    END IF;

    v_nf_ids := array_append(v_nf_ids, v_nf.id);
    v_dedupe := format('operacao:%s:nf:%s:%s', v_nf.operacao_id, v_nf.id, p_acao);

    INSERT INTO public.logs_auditoria (usuario_id, ator_tipo, origem, tipo_evento, entidade_tipo, entidade_id, dados_depois)
    VALUES (v_user_id, 'usuario', 'rpc_sacado', v_event, 'notas_fiscais', v_nf.id,
            jsonb_build_object('sacado_cnpj', v_sacado_cnpj, 'motivo', CASE WHEN p_acao = 'contestar' THEN p_motivo ELSE NULL END));

    FOR v_recipient IN
      SELECT c.user_id FROM public.cedentes c WHERE c.id = v_nf.cedente_id
      UNION
      SELECT ca.user_id FROM public.cedente_acessos ca WHERE ca.cedente_id = v_nf.cedente_id AND ca.ativo = true
    LOOP
      INSERT INTO public.notificacoes (usuario_id, titulo, mensagem, tipo, dedupe_key)
      VALUES (
        v_recipient,
        CASE WHEN p_acao = 'contestar' THEN 'Cessão contestada pelo sacado' ELSE 'Aceite de cessão confirmado' END,
        CASE WHEN p_acao = 'contestar' THEN v_message || '. O gestor foi notificado.' ELSE v_message END,
        CASE WHEN p_acao = 'contestar' THEN 'cessao_contestada' ELSE 'cessao_aceita' END,
        v_dedupe || ':cedente:' || v_recipient::text
      ) ON CONFLICT (usuario_id, dedupe_key) DO NOTHING;
    END LOOP;

    FOR v_recipient IN SELECT p.id FROM public.profiles p WHERE p.role = 'gestor'
    LOOP
      INSERT INTO public.notificacoes (usuario_id, titulo, mensagem, tipo, dedupe_key)
      VALUES (
        v_recipient,
        v_title,
        CASE WHEN p_acao = 'contestar' THEN v_message ELSE v_message || format(' (emitente: %s).', v_nf.razao_social_emitente) END,
        CASE WHEN p_acao = 'contestar' THEN 'cessao_contestada' ELSE 'cessao_aceita' END,
        v_dedupe || ':gestor:' || v_recipient::text
      ) ON CONFLICT (usuario_id, dedupe_key) DO NOTHING;
    END LOOP;
  END LOOP;

  -- Consolidação ocorre sob os locks das operações obtidos acima.
  FOR v_op IN SELECT id, cedente_id FROM public.operacoes WHERE id = ANY(v_operation_ids) ORDER BY id LOOP
    SELECT count(*), count(*) FILTER (WHERE nf.status = 'aceita')
      INTO v_total, v_aceitas
      FROM public.operacoes_nfs onf
      JOIN public.notas_fiscais nf ON nf.id = onf.nota_fiscal_id
     WHERE onf.operacao_id = v_op.id;

    IF p_acao = 'contestar' THEN
      UPDATE public.operacoes SET aceite_sacado_status = 'contestado', aceite_sacado_em = now() WHERE id = v_op.id;
    ELSIF v_total > 0 AND v_total = v_aceitas THEN
      UPDATE public.operacoes SET aceite_sacado_status = 'aceito', aceite_sacado_em = now() WHERE id = v_op.id;
    END IF;
  END LOOP;

  RETURN jsonb_build_object('acao', p_acao, 'nota_fiscal_ids', to_jsonb(v_nf_ids), 'operacao_ids', to_jsonb(v_operation_ids));
END;
$function$

CREATE OR REPLACE FUNCTION public.processar_prazos_entrega(p_data date DEFAULT (now())::date)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  entrega record;
  cte_alertas integer := 0;
  canhoto_alertas integer := 0;
BEGIN
  IF get_user_role() NOT IN ('gestor') AND coalesce(current_setting('request.jwt.claim.role', true), '') <> 'service_role' THEN
    RAISE EXCEPTION 'Sem permissao para processar prazos';
  END IF;

  FOR entrega IN
    SELECT nfe.*, op.cedente_id, c.user_id
    FROM public.nota_fiscal_entregas nfe
    JOIN public.operacoes op ON op.id = nfe.operacao_id
    JOIN public.cedentes c ON c.id = op.cedente_id
    WHERE nfe.status_entrega IN ('em_transito', 'aguardando_validacao', 'entrega_com_pendencia')
  LOOP
    IF entrega.data_limite_cte IS NOT NULL AND entrega.data_limite_cte <= p_data THEN
      INSERT INTO public.notificacoes (usuario_id, titulo, mensagem, tipo, dedupe_key)
      VALUES (entrega.user_id, 'CT-e vencido', 'O prazo de CT-e de uma NF antecipada venceu.', 'cte_vencido', 'entrega:' || entrega.id::text || ':cte_vencido')
      ON CONFLICT (usuario_id, dedupe_key) DO NOTHING;
      IF NOT EXISTS (
        SELECT 1 FROM public.eventos_entrega ev
        WHERE ev.nota_fiscal_entrega_id = entrega.id
          AND ev.tipo_evento = 'cte_atrasado'
          AND ev.dados->>'data_referencia' = p_data::text
      ) THEN
        INSERT INTO public.eventos_entrega (nota_fiscal_entrega_id, tipo_evento, status_anterior, status_novo, ator_tipo, dados)
        VALUES (entrega.id, 'cte_atrasado', entrega.status_entrega, 'entrega_com_pendencia', 'cron', jsonb_build_object('data_referencia', p_data));
      END IF;
      UPDATE public.nota_fiscal_entregas SET status_entrega = 'entrega_com_pendencia', motivo_pendencia = 'CT-e vencido' WHERE id = entrega.id AND status_entrega <> 'entregue';
      UPDATE public.documento_requisito_instancias SET status = 'vencido' WHERE nota_fiscal_entrega_id = entrega.id AND tipo_documento_codigo_snapshot = 'cte' AND status = 'pendente';
      cte_alertas := cte_alertas + 1;
    ELSIF entrega.data_limite_cte IS NOT NULL AND entrega.data_limite_cte - 2 = p_data THEN
      INSERT INTO public.notificacoes (usuario_id, titulo, mensagem, tipo, dedupe_key)
      VALUES (entrega.user_id, 'CT-e proximo do prazo', 'O prazo de CT-e vence em 2 dias corridos.', 'cte_prazo_proximo', 'entrega:' || entrega.id::text || ':cte_d8')
      ON CONFLICT (usuario_id, dedupe_key) DO NOTHING;
      cte_alertas := cte_alertas + 1;
    END IF;

    IF entrega.data_limite_canhoto IS NOT NULL AND entrega.data_limite_canhoto <= p_data THEN
      INSERT INTO public.notificacoes (usuario_id, titulo, mensagem, tipo, dedupe_key)
      VALUES (entrega.user_id, 'Canhoto vencido', 'O prazo de canhoto de uma NF antecipada venceu.', 'canhoto_vencido', 'entrega:' || entrega.id::text || ':canhoto_vencido')
      ON CONFLICT (usuario_id, dedupe_key) DO NOTHING;
      IF NOT EXISTS (
        SELECT 1 FROM public.eventos_entrega ev
        WHERE ev.nota_fiscal_entrega_id = entrega.id
          AND ev.tipo_evento = 'canhoto_atrasado'
          AND ev.dados->>'data_referencia' = p_data::text
      ) THEN
        INSERT INTO public.eventos_entrega (nota_fiscal_entrega_id, tipo_evento, status_anterior, status_novo, ator_tipo, dados)
        VALUES (entrega.id, 'canhoto_atrasado', entrega.status_entrega, 'entrega_com_pendencia', 'cron', jsonb_build_object('data_referencia', p_data));
      END IF;
      UPDATE public.nota_fiscal_entregas SET status_entrega = 'entrega_com_pendencia', motivo_pendencia = 'Canhoto vencido' WHERE id = entrega.id AND status_entrega <> 'entregue';
      UPDATE public.documento_requisito_instancias SET status = 'vencido' WHERE nota_fiscal_entrega_id = entrega.id AND tipo_documento_codigo_snapshot = 'canhoto' AND status = 'pendente';
      canhoto_alertas := canhoto_alertas + 1;
    ELSIF entrega.data_limite_canhoto IS NOT NULL AND entrega.data_limite_canhoto - 4 = p_data THEN
      INSERT INTO public.notificacoes (usuario_id, titulo, mensagem, tipo, dedupe_key)
      VALUES (entrega.user_id, 'Canhoto proximo do prazo', 'O prazo de canhoto vence em 4 dias corridos.', 'canhoto_prazo_proximo', 'entrega:' || entrega.id::text || ':canhoto_d16')
      ON CONFLICT (usuario_id, dedupe_key) DO NOTHING;
      canhoto_alertas := canhoto_alertas + 1;
    END IF;
  END LOOP;

  RETURN jsonb_build_object('cte_alertas', cte_alertas, 'canhoto_alertas', canhoto_alertas, 'data', p_data);
END;
$function$

CREATE OR REPLACE FUNCTION public.reconciliar_documentos_base_nf_existentes()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  nf record;
  resultado jsonb;
  total_nf integer := 0;
  total_satisfeitas integer := 0;
  total_pendentes integer := 0;
  total_divergencias integer := 0;
BEGIN
  IF auth.uid() IS NULL OR get_user_role() <> 'gestor' THEN
    RAISE EXCEPTION 'Somente gestor pode executar o reparo administrativo do checklist';
  END IF;

  FOR nf IN
    SELECT DISTINCT dri.nota_fiscal_id
    FROM public.documento_requisito_instancias dri
    WHERE dri.nota_fiscal_id IS NOT NULL
      AND dri.escopo_snapshot = 'nf_pre_cessao'
      AND dri.tipo_documento_codigo_snapshot IN ('nf_xml', 'nf_danfe_pdf')
  LOOP
    resultado := public.reconciliar_documentos_base_nf(nf.nota_fiscal_id);
    total_nf := total_nf + 1;
    total_satisfeitas := total_satisfeitas + COALESCE((resultado->>'instanciasSatisfeitas')::integer, 0);
    total_pendentes := total_pendentes + COALESCE((resultado->>'instanciasPendentes')::integer, 0);
    total_divergencias := total_divergencias + COALESCE((resultado->>'divergencias')::integer, 0);
  END LOOP;

  RETURN jsonb_build_object(
    'notasFiscaisProcessadas', total_nf,
    'instanciasSatisfeitas', total_satisfeitas,
    'instanciasPendentes', total_pendentes,
    'divergencias', total_divergencias,
    'modo', 'reparo_administrativo'
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.registrar_canhoto_documento(p_nota_fiscal_entrega_id uuid, p_nome_original text, p_mime_type text, p_tamanho_bytes bigint, p_sha256 text, p_bucket text, p_path text, p_data_assinatura date DEFAULT NULL::date, p_nome_recebedor text DEFAULT NULL::text, p_documento_recebedor text DEFAULT NULL::text, p_possui_assinatura boolean DEFAULT false, p_possui_ressalva boolean DEFAULT false, p_descricao_ressalva text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  actor_role text := get_user_role();
  actor_id uuid := auth.uid();
  entrega record;
  tipo record;
  doc_id uuid;
  version_id uuid;
  canhoto_id uuid;
BEGIN
  IF actor_id IS NULL OR actor_role NOT IN ('cedente', 'gestor') THEN
    RAISE EXCEPTION 'Usuario sem permissao para enviar canhoto';
  END IF;
  SELECT nfe.*, op.cedente_id INTO entrega
  FROM public.nota_fiscal_entregas nfe
  JOIN public.operacoes op ON op.id = nfe.operacao_id
  WHERE nfe.id = p_nota_fiscal_entrega_id;
  IF entrega.id IS NULL OR entrega.status_entrega IN ('nao_aplicavel', 'cancelada', 'devolvida', 'entregue') THEN
    RAISE EXCEPTION 'Entrega nao esta aberta para canhoto';
  END IF;
  IF actor_role = 'cedente' AND entrega.cedente_id <> get_user_cedente_id() THEN
    RAISE EXCEPTION 'Entrega fora do cedente autenticado';
  END IF;
  IF p_possui_ressalva AND length(trim(coalesce(p_descricao_ressalva, ''))) = 0 THEN
    RAISE EXCEPTION 'Descricao da ressalva e obrigatoria';
  END IF;
  IF p_bucket <> 'documentos-v2' OR p_tamanho_bytes <= 0 OR p_sha256 !~ '^[0-9a-fA-F]{64}$' THEN
    RAISE EXCEPTION 'Metadados de armazenamento invalidos';
  END IF;
  SELECT * INTO tipo FROM public.documento_tipos WHERE codigo = 'canhoto' AND ativo = true;
  IF tipo.id IS NULL OR lower(p_mime_type) <> ALL (SELECT lower(unnest(tipo.mime_types_aceitos))) THEN
    RAISE EXCEPTION 'Arquivo de canhoto em formato invalido';
  END IF;

  INSERT INTO public.documentos_repositorio (documento_tipo_id, status, criado_por)
  VALUES (tipo.id, 'enviado', actor_id)
  RETURNING id INTO doc_id;

  INSERT INTO public.documento_versoes (
    documento_id, numero_versao, bucket, path, nome_original, mime_type, tamanho_bytes, sha256,
    status, enviado_por
  )
  VALUES (doc_id, 1, p_bucket, p_path, p_nome_original, lower(p_mime_type), p_tamanho_bytes, lower(p_sha256), 'em_analise', actor_id)
  RETURNING id INTO version_id;

  INSERT INTO public.documento_vinculos (documento_id, nota_fiscal_entrega_id, cedente_id)
  VALUES (doc_id, p_nota_fiscal_entrega_id, entrega.cedente_id);

  INSERT INTO public.canhotos (
    nota_fiscal_entrega_id, status, data_assinatura, nome_recebedor,
    documento_recebedor, possui_assinatura, possui_ressalva, descricao_ressalva,
    recebido_em, documento_id, documento_versao_atual_id
  )
  VALUES (
    p_nota_fiscal_entrega_id, 'em_analise', p_data_assinatura, p_nome_recebedor,
    NULLIF(regexp_replace(coalesce(p_documento_recebedor, ''), '\D', '', 'g'), ''), coalesce(p_possui_assinatura, false),
    coalesce(p_possui_ressalva, false), p_descricao_ressalva, now(), doc_id, version_id
  )
  RETURNING id INTO canhoto_id;

  PERFORM public.registrar_evento_entrega(p_nota_fiscal_entrega_id, 'canhoto_enviado', entrega.status_entrega, entrega.status_entrega, 'usuario', jsonb_build_object('canhoto_id', canhoto_id, 'versao_id', version_id));

  INSERT INTO public.notificacoes (usuario_id, titulo, mensagem, tipo, dedupe_key)
  SELECT p.id, 'Canhoto enviado', 'Um canhoto foi enviado para analise.', 'canhoto_enviado',
         'canhoto:' || canhoto_id::text || ':enviado:' || p.id::text
  FROM public.profiles p WHERE p.role = 'gestor'
  ON CONFLICT (usuario_id, dedupe_key) DO NOTHING;

  RETURN jsonb_build_object('canhoto_id', canhoto_id, 'documento_id', doc_id, 'versao_id', version_id);
END;
$function$

CREATE OR REPLACE FUNCTION public.registrar_cte_documento(p_nota_fiscal_ids uuid[], p_documento_tipo_codigo text, p_nome_original text, p_mime_type text, p_tamanho_bytes bigint, p_sha256 text, p_bucket text, p_path text, p_chave_cte text DEFAULT NULL::text, p_numero text DEFAULT NULL::text, p_serie text DEFAULT NULL::text, p_data_emissao date DEFAULT NULL::date, p_cnpj_transportadora text DEFAULT NULL::text, p_cnpj_remetente text DEFAULT NULL::text, p_cnpj_destinatario text DEFAULT NULL::text, p_valor_frete numeric DEFAULT NULL::numeric, p_nivel_validacao text DEFAULT 'manual'::text, p_dados_extraidos jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  actor_role text := get_user_role();
  actor_id uuid := auth.uid();
  tipo record;
  cedente uuid;
  fundo uuid;
  cedente_fundo uuid;
  nf_count integer;
  expected_count integer;
  delivery record;
  v_doc_id uuid;
  v_version_id uuid;
  v_cte_id uuid;
  formato text;
  resultado jsonb := coalesce(p_dados_extraidos->'resultado_validacao', '{}'::jsonb);
  status_validacao text := coalesce(nullif(resultado->>'status', ''), 'validacao_parcial');
BEGIN
  IF actor_id IS NULL OR actor_role NOT IN ('cedente', 'gestor') THEN
    RAISE EXCEPTION 'Usuario sem permissao para enviar CT-e';
  END IF;
  IF p_nota_fiscal_ids IS NULL OR cardinality(p_nota_fiscal_ids) = 0 THEN
    RAISE EXCEPTION 'Informe ao menos uma NF para o CT-e';
  END IF;
  IF p_bucket <> 'documentos-v2' OR p_tamanho_bytes <= 0 OR p_sha256 !~ '^[0-9a-fA-F]{64}$' THEN
    RAISE EXCEPTION 'Metadados de armazenamento invalidos';
  END IF;

  SELECT * INTO tipo FROM public.documento_tipos WHERE codigo = p_documento_tipo_codigo AND ativo = true;
  IF tipo.id IS NULL OR p_documento_tipo_codigo NOT IN ('cte_xml', 'cte_pdf_dacte') THEN
    RAISE EXCEPTION 'Tipo documental de CT-e invalido';
  END IF;
  IF lower(p_mime_type) <> ALL (SELECT lower(unnest(tipo.mime_types_aceitos))) THEN
    RAISE EXCEPTION 'MIME type nao permitido para CT-e';
  END IF;

  SELECT count(DISTINCT nf_id) INTO expected_count
  FROM unnest(p_nota_fiscal_ids) AS item(nf_id);

  SELECT n.cedente_id, n.fundo_id, n.cedente_fundo_id, count(DISTINCT n.id)
    INTO cedente, fundo, cedente_fundo, nf_count
  FROM public.notas_fiscais n
  JOIN public.nota_fiscal_entregas nfe ON nfe.nota_fiscal_id = n.id
  WHERE n.id = ANY(p_nota_fiscal_ids)
    AND n.fundo_id IS NOT NULL
    AND n.cedente_fundo_id IS NOT NULL
    AND nfe.status_entrega NOT IN ('nao_aplicavel', 'cancelada', 'devolvida')
  GROUP BY n.cedente_id, n.fundo_id, n.cedente_fundo_id;

  IF cedente IS NULL OR fundo IS NULL OR cedente_fundo IS NULL OR nf_count <> expected_count THEN
    RAISE EXCEPTION 'As NFs precisam estar em acompanhamento ativo e pertencer ao mesmo cedente, fundo e vinculo';
  END IF;
  IF actor_role = 'cedente' AND cedente <> get_user_cedente_id() THEN
    RAISE EXCEPTION 'NF fora do cedente autenticado';
  END IF;
  IF actor_role = 'gestor' AND to_regclass('public.usuario_fundos') IS NOT NULL THEN
    IF NOT EXISTS (
      SELECT 1
      FROM public.usuario_fundos uf
      WHERE uf.usuario_id = actor_id
        AND uf.fundo_id = fundo
        AND uf.status = 'ativo'
    ) THEN
      RAISE EXCEPTION 'Fundo nao autorizado para o gestor autenticado';
    END IF;
  END IF;

  IF NOT EXISTS (
    SELECT 1
    FROM public.documento_requisito_instancias dri
    JOIN public.nota_fiscal_entregas nfe ON nfe.id = dri.nota_fiscal_entrega_id
    WHERE nfe.nota_fiscal_id = ANY(p_nota_fiscal_ids)
      AND dri.tipo_documento_codigo_snapshot IN ('cte', 'cte_xml')
      AND dri.status NOT IN ('cancelado', 'dispensado')
  ) THEN
    RAISE EXCEPTION 'CT-e nao esta configurado como requisito documental para esta NF/operaÃ§Ã£o';
  END IF;

  IF p_chave_cte IS NOT NULL AND EXISTS (SELECT 1 FROM public.ctes WHERE chave_cte = p_chave_cte) THEN
    RAISE EXCEPTION 'Chave de CT-e ja cadastrada';
  END IF;

  IF p_documento_tipo_codigo = 'cte_xml' AND status_validacao = 'rejeitado' THEN
    RAISE EXCEPTION 'CT-e incompativel com a NF-e';
  END IF;

  formato := CASE WHEN p_documento_tipo_codigo = 'cte_xml' THEN 'xml' ELSE 'pdf' END;

  INSERT INTO public.documentos_repositorio (documento_tipo_id, status, criado_por)
  VALUES (tipo.id, 'enviado', actor_id)
  RETURNING id INTO v_doc_id;

  INSERT INTO public.documento_versoes (
    documento_id, numero_versao, bucket, path, nome_original, mime_type, tamanho_bytes, sha256,
    status, enviado_por
  )
  VALUES (v_doc_id, 1, p_bucket, p_path, p_nome_original, lower(p_mime_type), p_tamanho_bytes, lower(p_sha256), 'em_analise', actor_id)
  RETURNING id INTO v_version_id;

  INSERT INTO public.ctes (
    fundo_id, cedente_id, cedente_fundo_id, chave_cte, numero, serie, data_emissao,
    ambiente, modelo, tipo_cte, tipo_servico, modal, cfop, natureza_operacao,
    protocolo, status_autorizacao, motivo_status, data_autorizacao,
    cnpj_transportadora, cnpj_remetente, cnpj_destinatario,
    transportadora_razao_social, transportadora_ie, rntrc, remetente_razao_social, destinatario_razao_social,
    municipio_origem_codigo, municipio_origem_nome, uf_origem,
    municipio_destino_codigo, municipio_destino_nome, uf_destino,
    valor_frete, valor_prestacao, valor_receber, valor_carga,
    produto_predominante, categoria_carga, quantidade_carga, unidade_carga,
    peso_bruto, peso_liquido, volume_quantidade, formato_origem, nivel_validacao,
    status, documento_id, documento_versao_atual_id, dados_extraidos, hash_sha256, uploaded_by, resultado_validacao
  )
  VALUES (
    fundo, cedente, cedente_fundo, p_chave_cte, p_numero, p_serie, p_data_emissao,
    nullif(p_dados_extraidos->>'ambiente', ''), nullif(p_dados_extraidos->>'modelo', ''),
    nullif(p_dados_extraidos->>'tipo_cte', ''), nullif(p_dados_extraidos->>'tipo_servico', ''),
    nullif(p_dados_extraidos->>'modal', ''), nullif(p_dados_extraidos->>'cfop', ''),
    nullif(p_dados_extraidos->>'natureza_operacao', ''), nullif(p_dados_extraidos->>'protocolo_autorizacao', ''),
    nullif(p_dados_extraidos->>'status_autorizacao', ''), nullif(p_dados_extraidos->>'motivo_status', ''),
    nullif(p_dados_extraidos->>'data_autorizacao', '')::timestamptz,
    NULLIF(regexp_replace(coalesce(p_cnpj_transportadora, ''), '\D', '', 'g'), ''),
    NULLIF(regexp_replace(coalesce(p_cnpj_remetente, ''), '\D', '', 'g'), ''),
    NULLIF(regexp_replace(coalesce(p_cnpj_destinatario, ''), '\D', '', 'g'), ''),
    nullif(p_dados_extraidos#>>'{transportadora,razao_social}', ''),
    nullif(p_dados_extraidos#>>'{transportadora,inscricao_estadual}', ''),
    nullif(p_dados_extraidos->>'rntrc', ''),
    nullif(p_dados_extraidos#>>'{remetente,razao_social}', ''),
    nullif(p_dados_extraidos#>>'{destinatario,razao_social}', ''),
    nullif(p_dados_extraidos->>'municipio_origem_codigo', ''),
    nullif(p_dados_extraidos->>'municipio_origem_nome', ''),
    nullif(p_dados_extraidos->>'uf_origem', ''),
    nullif(p_dados_extraidos->>'municipio_destino_codigo', ''),
    nullif(p_dados_extraidos->>'municipio_destino_nome', ''),
    nullif(p_dados_extraidos->>'uf_destino', ''),
    p_valor_frete,
    nullif(p_dados_extraidos->>'valor_prestacao', '')::numeric,
    nullif(p_dados_extraidos->>'valor_receber', '')::numeric,
    nullif(p_dados_extraidos->>'valor_carga', '')::numeric,
    nullif(p_dados_extraidos->>'produto_predominante', ''),
    nullif(p_dados_extraidos->>'categoria_carga', ''),
    nullif(p_dados_extraidos->>'quantidade_carga', '')::numeric,
    nullif(p_dados_extraidos->>'unidade_carga', ''),
    nullif(p_dados_extraidos->>'peso_bruto', '')::numeric,
    nullif(p_dados_extraidos->>'peso_liquido', '')::numeric,
    nullif(p_dados_extraidos->>'volume_quantidade', '')::numeric,
    formato, p_nivel_validacao, 'em_analise', v_doc_id, v_version_id,
    coalesce(p_dados_extraidos, '{}'::jsonb) - 'xml_original',
    lower(p_sha256), actor_id, resultado
  )
  RETURNING id INTO v_cte_id;

  INSERT INTO public.documento_vinculos (documento_id, cte_id, cedente_id)
  VALUES (v_doc_id, v_cte_id, cedente);

  INSERT INTO public.documento_vinculos (documento_id, nota_fiscal_entrega_id, cedente_id, principal)
  SELECT v_doc_id, nfe.id, cedente, false
  FROM public.nota_fiscal_entregas nfe
  WHERE nfe.nota_fiscal_id = ANY(p_nota_fiscal_ids)
  ON CONFLICT DO NOTHING;

  INSERT INTO public.cte_notas_fiscais (
    cte_id, nota_fiscal_id, chave_nfe_referenciada, status_validacao, resultado_validacao, divergencias, validado_em
  )
  SELECT
    v_cte_id,
    n.id,
    n.chave_acesso,
    coalesce(nullif(vnf.item->>'status', ''), status_validacao),
    coalesce(vnf.item, resultado),
    coalesce((vnf.item->'bloqueios') || (vnf.item->'alertas'), '[]'::jsonb),
    now()
  FROM public.notas_fiscais n
  LEFT JOIN LATERAL (
    SELECT item
    FROM jsonb_array_elements(coalesce(resultado->'validacoesPorNf', '[]'::jsonb)) item
    WHERE item->>'notaFiscalId' = n.id::text
    LIMIT 1
  ) vnf ON true
  WHERE n.id = ANY(p_nota_fiscal_ids);

  UPDATE public.documento_requisito_instancias dri
  SET documento_id = v_doc_id,
      versao_aprovada_id = NULL,
      status = 'pendente',
      satisfeito_em = NULL
  FROM public.nota_fiscal_entregas nfe
  WHERE dri.nota_fiscal_entrega_id = nfe.id
    AND nfe.nota_fiscal_id = ANY(p_nota_fiscal_ids)
    AND dri.tipo_documento_codigo_snapshot IN ('cte', 'cte_xml')
    AND dri.status NOT IN ('cancelado', 'dispensado');

  FOR delivery IN
    SELECT nfe.* FROM public.nota_fiscal_entregas nfe WHERE nfe.nota_fiscal_id = ANY(p_nota_fiscal_ids)
  LOOP
    PERFORM public.registrar_evento_entrega(delivery.id, 'cte_enviado', delivery.status_entrega, delivery.status_entrega, 'usuario', jsonb_build_object('cte_id', v_cte_id, 'versao_id', v_version_id, 'resultado_validacao', status_validacao));
  END LOOP;

  INSERT INTO public.notificacoes (usuario_id, titulo, mensagem, tipo, dedupe_key)
  SELECT p.id, 'CT-e enviado', 'Um CT-e foi enviado para analise.', 'cte_enviado',
         'cte:' || v_cte_id::text || ':enviado:' || p.id::text
  FROM public.profiles p WHERE p.role = 'gestor'
  ON CONFLICT (usuario_id, dedupe_key) DO NOTHING;

  RETURN jsonb_build_object(
    'cte_id', v_cte_id,
    'documento_id', v_doc_id,
    'versao_id', v_version_id,
    'status_validacao', status_validacao,
    'resultado_validacao', resultado
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.registrar_documento_entrega_upload(p_nota_fiscal_entrega_id uuid, p_requisito_id uuid, p_documento_tipo_id uuid, p_nome_original text, p_mime_type text, p_tamanho_bytes bigint, p_sha256 text, p_bucket text, p_path text, p_enviado_por uuid, p_substitui_versao_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  actor_role text := get_user_role();
  actor_id uuid := auth.uid();
  entrega record;
  requirement record;
  doc_id uuid;
  version_id uuid;
  version_number integer;
  same_hash boolean;
BEGIN
  IF actor_id IS NULL OR actor_role NOT IN ('gestor', 'cedente') OR p_enviado_por <> actor_id THEN
    RAISE EXCEPTION 'Usuario sem permissao para enviar documento de entrega';
  END IF;

  SELECT nfe.*, n.cedente_id, n.cedente_fundo_id, n.fundo_id
    INTO entrega
  FROM public.nota_fiscal_entregas nfe
  JOIN public.notas_fiscais n ON n.id = nfe.nota_fiscal_id
  WHERE nfe.id = p_nota_fiscal_entrega_id
  FOR UPDATE;

  IF entrega.id IS NULL THEN RAISE EXCEPTION 'Entrega documental nao encontrada'; END IF;
  IF entrega.status_entrega IN ('nao_aplicavel', 'cancelada', 'devolvida', 'entregue') THEN
    RAISE EXCEPTION 'Entrega nao esta aberta para upload documental';
  END IF;
  IF entrega.cedente_fundo_id IS NULL OR entrega.fundo_id IS NULL THEN
    RAISE EXCEPTION 'Nota fiscal sem contexto cedente-fundo/fundo';
  END IF;
  IF actor_role = 'cedente' AND entrega.cedente_id <> get_user_cedente_id() THEN
    RAISE EXCEPTION 'Entrega fora do cedente autenticado';
  END IF;

  SELECT * INTO requirement
  FROM public.documento_requisito_instancias
  WHERE id = p_requisito_id
    AND nota_fiscal_entrega_id = p_nota_fiscal_entrega_id
    AND status NOT IN ('cancelado', 'satisfeito')
  FOR UPDATE;

  IF requirement.id IS NULL THEN RAISE EXCEPTION 'Requisito documental de entrega invalido ou ja satisfeito'; END IF;
  IF requirement.cedente_id <> entrega.cedente_id THEN RAISE EXCEPTION 'Requisito documental fora do cedente da entrega'; END IF;
  IF NOT public.documento_tipo_compativel_com_requisito(requirement.tipo_documento_codigo_snapshot, p_documento_tipo_id) THEN
    RAISE EXCEPTION 'Tipo de documento nao corresponde ao requisito';
  END IF;
  IF p_bucket <> 'documentos-v2' OR length(p_path) = 0 OR p_tamanho_bytes <= 0 OR p_sha256 !~ '^[0-9a-fA-F]{64}$' THEN
    RAISE EXCEPTION 'Metadados de armazenamento invalidos';
  END IF;

  doc_id := requirement.documento_id;
  IF doc_id IS NULL THEN
    INSERT INTO public.documentos_repositorio (documento_tipo_id, status, criado_por)
    VALUES (p_documento_tipo_id, 'pendente', p_enviado_por)
    RETURNING id INTO doc_id;

    INSERT INTO public.documento_vinculos (documento_id, nota_fiscal_entrega_id, cedente_id)
    VALUES (doc_id, p_nota_fiscal_entrega_id, entrega.cedente_id);
  ELSE
    UPDATE public.documentos_repositorio
    SET documento_tipo_id = p_documento_tipo_id
    WHERE id = doc_id
      AND documento_tipo_id IS DISTINCT FROM p_documento_tipo_id;
  END IF;

  PERFORM pg_advisory_xact_lock(hashtextextended(doc_id::text, 0));
  SELECT COALESCE(max(numero_versao), 0) + 1 INTO version_number
  FROM public.documento_versoes WHERE documento_id = doc_id;
  SELECT EXISTS (SELECT 1 FROM public.documento_versoes WHERE documento_id = doc_id AND sha256 = lower(p_sha256)) INTO same_hash;

  INSERT INTO public.documento_versoes (
    documento_id, numero_versao, bucket, path, nome_original, mime_type, tamanho_bytes, sha256,
    status, substitui_versao_id, enviado_por
  ) VALUES (
    doc_id, version_number, p_bucket, p_path, p_nome_original, lower(p_mime_type), p_tamanho_bytes, lower(p_sha256),
    'em_analise', p_substitui_versao_id, p_enviado_por
  ) RETURNING id INTO version_id;

  UPDATE public.documentos_repositorio SET status = 'em_analise', deleted_at = NULL WHERE id = doc_id;
  UPDATE public.documento_requisito_instancias
  SET documento_id = doc_id,
      documento_tipo_id = p_documento_tipo_id,
      versao_aprovada_id = NULL,
      status = 'pendente',
      satisfeito_em = NULL
  WHERE id = p_requisito_id;

  IF entrega.status_entrega IN ('em_transito', 'entrega_com_pendencia') THEN
    UPDATE public.nota_fiscal_entregas
    SET status_entrega = 'aguardando_validacao',
        motivo_pendencia = NULL
    WHERE id = p_nota_fiscal_entrega_id;
  END IF;

  PERFORM public.registrar_evento_entrega(
    p_nota_fiscal_entrega_id,
    CASE
      WHEN requirement.tipo_documento_codigo_snapshot = 'cte' THEN 'cte_enviado'
      ELSE 'documento_entrega_enviado'
    END,
    entrega.status_entrega,
    'aguardando_validacao',
    'usuario',
    jsonb_build_object('requisito_id', p_requisito_id, 'versao_id', version_id, 'tipo_documento_codigo', requirement.tipo_documento_codigo_snapshot)
  );

  RETURN jsonb_build_object(
    'documento_id', doc_id,
    'versao_id', version_id,
    'numero_versao', version_number,
    'sha256_igual', same_hash,
    'nota_fiscal_entrega_id', p_nota_fiscal_entrega_id,
    'cedente_fundo_id', entrega.cedente_fundo_id,
    'fundo_id', entrega.fundo_id
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.registrar_documento_upload(p_nota_fiscal_id uuid, p_requisito_id uuid, p_documento_tipo_id uuid, p_nome_original text, p_mime_type text, p_tamanho_bytes bigint, p_sha256 text, p_bucket text, p_path text, p_enviado_por uuid, p_substitui_versao_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  actor_role text;
  nf_cedente uuid;
  nf_cedente_fundo uuid;
  nf_fundo uuid;
  requirement record;
  doc_id uuid;
  version_id uuid;
  version_number integer;
  same_hash boolean;
BEGIN
  actor_role := get_user_role();
  IF auth.uid() IS NULL OR actor_role NOT IN ('gestor', 'cedente') OR p_enviado_por <> auth.uid() THEN
    RAISE EXCEPTION 'Usuario sem permissao para enviar documento';
  END IF;

  SELECT cedente_id, cedente_fundo_id, fundo_id
    INTO nf_cedente, nf_cedente_fundo, nf_fundo
  FROM public.notas_fiscais
  WHERE id = p_nota_fiscal_id;

  IF nf_cedente IS NULL THEN RAISE EXCEPTION 'Nota fiscal nao encontrada'; END IF;
  IF nf_cedente_fundo IS NULL OR nf_fundo IS NULL THEN
    RAISE EXCEPTION 'Nota fiscal sem contexto cedente-fundo/fundo';
  END IF;
  IF actor_role = 'cedente' AND nf_cedente <> get_user_cedente_id() THEN RAISE EXCEPTION 'NF fora do cedente autenticado'; END IF;

  SELECT * INTO requirement
  FROM public.documento_requisito_instancias
  WHERE id = p_requisito_id
    AND nota_fiscal_id = p_nota_fiscal_id
    AND status NOT IN ('cancelado', 'satisfeito')
  FOR UPDATE;

  IF requirement.id IS NULL THEN RAISE EXCEPTION 'Requisito documental invalido ou ja satisfeito'; END IF;
  IF requirement.cedente_id <> nf_cedente THEN RAISE EXCEPTION 'Requisito documental fora do cedente da NF'; END IF;
  IF NOT public.documento_tipo_compativel_com_requisito(requirement.tipo_documento_codigo_snapshot, p_documento_tipo_id) THEN
    RAISE EXCEPTION 'Tipo de documento nao corresponde ao requisito';
  END IF;
  IF p_bucket <> 'documentos-v2' OR length(p_path) = 0 OR p_tamanho_bytes <= 0 OR p_sha256 !~ '^[0-9a-fA-F]{64}$' THEN
    RAISE EXCEPTION 'Metadados de armazenamento invalidos';
  END IF;

  doc_id := requirement.documento_id;
  IF doc_id IS NULL THEN
    INSERT INTO public.documentos_repositorio (documento_tipo_id, status, criado_por)
    VALUES (p_documento_tipo_id, 'pendente', p_enviado_por)
    RETURNING id INTO doc_id;

    INSERT INTO public.documento_vinculos (documento_id, nota_fiscal_id, cedente_id)
    VALUES (doc_id, p_nota_fiscal_id, nf_cedente);
  ELSE
    UPDATE public.documentos_repositorio
    SET documento_tipo_id = p_documento_tipo_id
    WHERE id = doc_id
      AND documento_tipo_id IS DISTINCT FROM p_documento_tipo_id;
  END IF;

  PERFORM pg_advisory_xact_lock(hashtextextended(doc_id::text, 0));
  SELECT COALESCE(max(numero_versao), 0) + 1 INTO version_number
  FROM public.documento_versoes WHERE documento_id = doc_id;
  SELECT EXISTS (SELECT 1 FROM public.documento_versoes WHERE documento_id = doc_id AND sha256 = lower(p_sha256)) INTO same_hash;

  INSERT INTO public.documento_versoes (
    documento_id, numero_versao, bucket, path, nome_original, mime_type, tamanho_bytes, sha256,
    status, substitui_versao_id, enviado_por
  ) VALUES (
    doc_id, version_number, p_bucket, p_path, p_nome_original, lower(p_mime_type), p_tamanho_bytes, lower(p_sha256),
    'em_analise', p_substitui_versao_id, p_enviado_por
  ) RETURNING id INTO version_id;

  UPDATE public.documentos_repositorio SET status = 'em_analise', deleted_at = NULL WHERE id = doc_id;
  UPDATE public.documento_requisito_instancias
  SET documento_id = doc_id,
      documento_tipo_id = p_documento_tipo_id,
      versao_aprovada_id = NULL,
      status = 'pendente',
      satisfeito_em = NULL
  WHERE id = p_requisito_id;

  RETURN jsonb_build_object(
    'documento_id', doc_id,
    'versao_id', version_id,
    'numero_versao', version_number,
    'sha256_igual', same_hash,
    'cedente_fundo_id', nf_cedente_fundo,
    'fundo_id', nf_fundo
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.revalidar_cte_nota_fiscal(p_cte_id uuid, p_nota_fiscal_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  actor_role text := get_user_role();
  actor_id uuid := auth.uid();
  link record;
BEGIN
  IF actor_id IS NULL OR actor_role <> 'gestor' THEN
    RAISE EXCEPTION 'Somente gestor pode revalidar CT-e';
  END IF;

  SELECT cnf.*, c.fundo_id, c.resultado_validacao
    INTO link
  FROM public.cte_notas_fiscais cnf
  JOIN public.ctes c ON c.id = cnf.cte_id
  WHERE cnf.cte_id = p_cte_id
    AND cnf.nota_fiscal_id = p_nota_fiscal_id;

  IF link.cte_id IS NULL THEN
    RAISE EXCEPTION 'Vinculo CT-e x NF-e nao encontrado';
  END IF;

  IF to_regclass('public.usuario_fundos') IS NOT NULL THEN
    IF NOT EXISTS (
      SELECT 1
      FROM public.usuario_fundos uf
      WHERE uf.usuario_id = actor_id
        AND uf.fundo_id = link.fundo_id
        AND uf.status = 'ativo'
    ) THEN
      RAISE EXCEPTION 'Fundo nao autorizado para o gestor autenticado';
    END IF;
  END IF;

  UPDATE public.cte_notas_fiscais
  SET validado_em = now(),
      resultado_validacao = coalesce(nullif(resultado_validacao, '{}'::jsonb), link.resultado_validacao, '{}'::jsonb)
  WHERE cte_id = p_cte_id
    AND nota_fiscal_id = p_nota_fiscal_id;

  INSERT INTO public.logs_auditoria (
    usuario_id, ator_tipo, origem, tipo_evento, entidade_tipo, entidade_id, dados_depois
  )
  VALUES (
    actor_id, 'usuario', 'app', 'CTE_REVALIDADO', 'ctes', p_cte_id,
    jsonb_build_object('nota_fiscal_id', p_nota_fiscal_id)
  );

  RETURN jsonb_build_object('cte_id', p_cte_id, 'nota_fiscal_id', p_nota_fiscal_id, 'revalidado_em', now());
END;
$function$

CREATE OR REPLACE FUNCTION public.revogar_match_manual(p_vinculo_id uuid, p_motivo text, p_correlation_id uuid DEFAULT gen_random_uuid())
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'auth', 'pg_temp'
AS $function$
DECLARE
  v_vinculo public.titulo_nf_vinculos%ROWTYPE;
  v_user_id uuid := auth.uid();
BEGIN
  SELECT * INTO v_vinculo FROM public.titulo_nf_vinculos WHERE id = p_vinculo_id FOR UPDATE;
  IF NOT FOUND OR NOT private.financeiro_gestor_tem_acesso_fundo(v_vinculo.fundo_id) THEN
    RAISE EXCEPTION USING ERRCODE = '42501', MESSAGE = 'Vinculo indisponivel para o fundo ativo';
  END IF;
  IF v_vinculo.origem <> 'MANUAL' THEN
    RAISE EXCEPTION USING ERRCODE = '22023', MESSAGE = 'Somente vinculo manual pode ser revogado por esta acao';
  END IF;
  IF v_vinculo.status = 'REVOGADO' THEN RETURN true; END IF;
  IF length(btrim(coalesce(p_motivo, ''))) < 5 THEN
    RAISE EXCEPTION USING ERRCODE = '22023', MESSAGE = 'Informe um motivo com pelo menos 5 caracteres';
  END IF;
  IF NOT private.financeiro_autorizacao_consumida('revogar_match_manual') THEN
    RAISE EXCEPTION USING ERRCODE = '42501', MESSAGE = 'Confirmacao TOTP fresca obrigatoria';
  END IF;

  UPDATE public.titulo_nf_vinculos
  SET status = 'REVOGADO', revogado_em = clock_timestamp(), revogado_por = v_user_id,
      motivo_revogacao = btrim(p_motivo)
  WHERE id = p_vinculo_id;

  INSERT INTO public.logs_auditoria (
    usuario_id, tipo_evento, entidade_tipo, entidade_id, dados_antes, dados_depois,
    ator_tipo, origem, ator_identificador
  ) VALUES (
    v_user_id, 'MATCH_MANUAL_REVOGADO', 'titulo_nf_vinculos', p_vinculo_id,
    jsonb_build_object('status', 'ATIVO', 'nota_fiscal_id', v_vinculo.nota_fiscal_id),
    jsonb_build_object('status', 'REVOGADO', 'motivo', btrim(p_motivo), 'correlation_id', p_correlation_id),
    'usuario', 'gestor_conciliacao', v_user_id::text
  );
  RETURN true;
END;
$function$

CREATE OR REPLACE FUNCTION public.validar_duplicata(p_duplicata_id uuid, p_resultado text, p_observacoes text, p_resultado_confronto jsonb)
 RETURNS duplicatas
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'private'
AS $function$
DECLARE
  v_user_id uuid := (SELECT auth.uid());
  v_role text := (SELECT public.get_user_role());
  v_row public.duplicatas%ROWTYPE;
  v_actor_name text;
  v_validation_id uuid;
BEGIN
  IF v_user_id IS NULL OR v_role <> 'gestor' THEN RAISE EXCEPTION 'Apenas gestor pode concluir a validacao'; END IF;
  IF p_resultado NOT IN ('VALIDADA', 'REJEITADA') THEN RAISE EXCEPTION 'Resultado de validacao invalido'; END IF;
  IF p_resultado = 'REJEITADA' AND length(btrim(coalesce(p_observacoes, ''))) = 0 THEN
    RAISE EXCEPTION 'Informe o motivo da rejeicao';
  END IF;
  SELECT * INTO v_row FROM public.duplicatas d WHERE d.id = p_duplicata_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Duplicata nao encontrada'; END IF;
  IF NOT (SELECT private.usuario_tem_acesso_fundo(v_row.fundo_id)) THEN RAISE EXCEPTION 'Gestor sem acesso ao fundo'; END IF;
  IF v_row.versao_atual_id IS NULL THEN RAISE EXCEPTION 'Duplicata sem versao documental'; END IF;
  IF p_resultado = 'VALIDADA' AND (
    v_row.numero IS NULL
    OR v_row.data_vencimento IS NULL
    OR v_row.valor_nominal IS NULL
    OR v_row.cnpj_cedente_documento IS NULL
    OR v_row.cnpj_sacado_documento IS NULL
    OR NOT EXISTS (
      SELECT 1
      FROM public.notas_fiscais nf
      WHERE nf.id = v_row.nota_fiscal_id
        AND regexp_replace(nf.cnpj_emitente, '[^0-9]', '', 'g') = v_row.cnpj_cedente_documento
        AND regexp_replace(nf.cnpj_destinatario, '[^0-9]', '', 'g') = v_row.cnpj_sacado_documento
    )
  ) THEN
    RAISE EXCEPTION 'Duplicata possui campos criticos ausentes ou partes divergentes da NF';
  END IF;

  INSERT INTO public.duplicata_validacoes (
    duplicata_id, duplicata_versao_id, resultado, observacoes,
    resultado_confronto, validado_por
  ) VALUES (
    v_row.id, v_row.versao_atual_id, p_resultado, nullif(btrim(p_observacoes), ''),
    coalesce(p_resultado_confronto, '{}'::jsonb), v_user_id
  ) RETURNING id INTO v_validation_id;

  UPDATE public.duplicatas SET
    status_validacao = p_resultado,
    validado_por = v_user_id,
    validado_em = now(),
    motivo_rejeicao = CASE WHEN p_resultado = 'REJEITADA' THEN btrim(p_observacoes) ELSE NULL END
  WHERE id = v_row.id RETURNING * INTO v_row;

  SELECT coalesce(p.nome_completo, p.email, 'Usuario') INTO v_actor_name FROM public.profiles p WHERE p.id = v_user_id;
  INSERT INTO public.eventos_dominio (
    tenant_id, fundo_id, cedente_id, cedente_fundo_id, nota_fiscal_id,
    tipo_evento, categoria, ator_usuario_id, ator_nome_snapshot,
    ator_perfil_snapshot, origem, descricao, metadata, visibilidade,
    origem_evento, origem_registro_id
  ) VALUES (
    v_row.fundo_id, v_row.fundo_id, v_row.cedente_id, v_row.cedente_fundo_id, v_row.nota_fiscal_id,
    CASE WHEN p_resultado = 'VALIDADA' THEN 'duplicata_validada' ELSE 'duplicata_rejeitada' END,
    CASE WHEN p_resultado = 'VALIDADA' THEN 'aprovacao' ELSE 'reprovacao' END,
    v_user_id, v_actor_name, v_role, 'app',
    CASE WHEN p_resultado = 'VALIDADA' THEN 'Duplicata validada pelo gestor.' ELSE 'Duplicata rejeitada pelo gestor.' END,
    jsonb_build_object('duplicata_id', v_row.id, 'resultado', p_resultado),
    'ambos', 'duplicata_validacoes', v_validation_id::text
  );
  RETURN v_row;
END;
$function$
